INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + quimioterapia neoadyuvante → pembrolizumab adyuvante', 'C50.9', 'Cáncer de mama triple negativo, estadio II-III (neoadyuvancia/adyuvancia)', NULL, 'Pembrolizumab 200 mg IV c/21 d + carboplatino AUC 5 c/21 d + paclitaxel 80 mg/m² semanal ×12 sem; luego pembrolizumab + doxorrubicina 60 mg/m² + ciclofosfamida 600 mg/m² c/21 d ×4; cirugía; pembrolizumab adyuvante hasta completar 9 ciclos', '["pembrolizumab", "carboplatino", "paclitaxel", "doxorrubicina", "ciclofosfamida"]'::jsonb, 'KEYNOTE-522', 'fase_3', 'Schmid P, et al. N Engl J Med 2020;382:810-821 (pCR 64,8% vs 51,2%; SLE 5 años 81,3%)', 'https://doi.org/10.1056/NEJMoa1910549', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('AC dosis densa → paclitaxel (adyuvante)', 'C50.9', 'Cáncer de mama operado, alto riesgo, adyuvancia', NULL, 'Doxorrubicina 60 mg/m² + ciclofosfamida 600 mg/m² IV c/14 d ×4 con filgrastim, seguido de paclitaxel 175 mg/m² IV c/14 d ×4', '["doxorrubicina", "ciclofosfamida", "paclitaxel", "filgrastim"]'::jsonb, 'CALGB 9741', 'fase_3', 'Citron ML, et al. J Clin Oncol 2003;21:1431-1439', 'https://doi.org/10.1200/JCO.2003.09.081', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TCHP neoadyuvante (docetaxel + carboplatino + trastuzumab + pertuzumab)', 'C50.9', 'Cáncer de mama HER2 positivo, estadio II-III, neoadyuvancia', NULL, 'Docetaxel 75 mg/m² + carboplatino AUC 6 + trastuzumab 8 mg/kg carga → 6 mg/kg + pertuzumab 840 mg carga → 420 mg, IV c/21 d ×6 ciclos', '["docetaxel", "carboplatino", "trastuzumab", "pertuzumab"]'::jsonb, 'TRAIN-2', 'fase_3', 'van Ramshorst MS, et al. Lancet Oncol 2018;19:1630-1640 (pCR 68%)', 'https://doi.org/10.1016/S1470-2045(18)30570-9', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab emtansina (T-DM1) adyuvante por enfermedad residual', 'C50.9', 'Cáncer de mama HER2 positivo con enfermedad residual tras neoadyuvancia', NULL, 'Trastuzumab emtansina 3,6 mg/kg IV c/21 d ×14 ciclos', '["trastuzumab emtansina"]'::jsonb, 'KATHERINE', 'fase_3', 'von Minckwitz G, et al. N Engl J Med 2019;380:617-628 (SLEi 3 años 88,3% vs 77,0%)', 'https://doi.org/10.1056/NEJMoa1814017', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab adyuvante 1 año', 'C50.9', 'Cáncer de mama HER2 positivo temprano, adyuvancia', NULL, 'Trastuzumab 8 mg/kg carga → 6 mg/kg IV c/21 d hasta completar 1 año (18 ciclos)', '["trastuzumab"]'::jsonb, 'HERA', 'fase_3', 'Piccart-Gebhart MJ, et al. N Engl J Med 2005;353:1659-1672', 'https://doi.org/10.1056/NEJMoa052306', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Ribociclib + letrozol', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado o metastásico, posmenopáusica', 1, 'Ribociclib 600 mg VO/d, días 1-21 c/28 d + letrozol 2,5 mg VO/d continuo', '["ribociclib", "letrozol"]'::jsonb, 'MONALEESA-2', 'fase_3', 'Hortobagyi GN, et al. N Engl J Med 2022;386:942-950 (SG final)', 'https://doi.org/10.1056/NEJMoa2114663', 25.3, 63.9, 42.5, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Abemaciclib + inhibidor de aromatasa no esteroideo', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado o metastásico', 1, 'Abemaciclib 150 mg VO c/12 h continuo + anastrozol 1 mg/d o letrozol 2,5 mg/d', '["abemaciclib", "letrozol", "anastrozol"]'::jsonb, 'MONARCH 3', 'fase_3', 'Goetz MP, et al. J Clin Oncol 2017;35:3638-3646; SG final: Goetz MP, et al. Ann Oncol 2024;35:718-727', 'https://doi.org/10.1200/JCO.2017.75.6155', 28.2, 66.8, 61.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Palbociclib + letrozol', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado o metastásico, posmenopáusica', 1, 'Palbociclib 125 mg VO/d, días 1-21 c/28 d + letrozol 2,5 mg VO/d', '["palbociclib", "letrozol"]'::jsonb, 'PALOMA-2', 'fase_3', 'Finn RS, et al. N Engl J Med 2016;375:1925-1936', 'https://doi.org/10.1056/NEJMoa1607303', 24.8, NULL, 42.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Ribociclib + fulvestrant', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado, 1ª o 2ª línea endocrina', 2, 'Ribociclib 600 mg VO/d, días 1-21 c/28 d + fulvestrant 500 mg IM días 1 y 15 del ciclo 1, luego c/28 d', '["ribociclib", "fulvestrant"]'::jsonb, 'MONALEESA-3', 'fase_3', 'Slamon DJ, et al. N Engl J Med 2020;382:514-524', 'https://doi.org/10.1056/NEJMoa1911149', 20.5, 53.7, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Everolimus + exemestano', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado, progresión a inhibidor de aromatasa no esteroideo', 2, 'Everolimus 10 mg VO/d + exemestano 25 mg VO/d', '["everolimus", "exemestano"]'::jsonb, 'BOLERO-2', 'fase_3', 'Baselga J, et al. N Engl J Med 2012;366:520-529', 'https://doi.org/10.1056/NEJMoa1109653', 7.8, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Alpelisib + fulvestrant (PIK3CA mutado)', 'C50.9', 'Cáncer de mama RH+/HER2- avanzado con mutación PIK3CA, progresión a terapia endocrina', 2, 'Alpelisib 300 mg VO/d + fulvestrant 500 mg IM días 1 y 15 del ciclo 1, luego c/28 d', '["alpelisib", "fulvestrant"]'::jsonb, 'SOLAR-1', 'fase_3', 'André F, et al. N Engl J Med 2019;380:1929-1940', 'https://doi.org/10.1056/NEJMoa1813904', 11.0, NULL, 26.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pertuzumab + trastuzumab + docetaxel', 'C50.9', 'Cáncer de mama HER2 positivo metastásico', 1, 'Pertuzumab 840 mg carga → 420 mg + trastuzumab 8 mg/kg carga → 6 mg/kg + docetaxel 75 mg/m², IV c/21 d (docetaxel ≥6 ciclos; doble bloqueo hasta progresión)', '["pertuzumab", "trastuzumab", "docetaxel"]'::jsonb, 'CLEOPATRA', 'fase_3', 'Swain SM, et al. Lancet Oncol 2020;21:519-530 (análisis final)', 'https://doi.org/10.1016/S1470-2045(19)30863-0', 18.7, 57.1, 80.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab deruxtecan (T-DXd)', 'C50.9', 'Cáncer de mama HER2 positivo metastásico, progresión a trastuzumab + taxano', 2, 'Trastuzumab deruxtecan 5,4 mg/kg IV c/21 d hasta progresión o toxicidad', '["trastuzumab deruxtecan"]'::jsonb, 'DESTINY-Breast03', 'fase_3', 'Hurvitz SA, et al. Lancet 2023;401:105-117', 'https://doi.org/10.1016/S0140-6736(22)02420-5', 28.8, NULL, 78.5, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab deruxtecan (HER2-low)', 'C50.9', 'Cáncer de mama HER2-low (IHQ 1+ o 2+/ISH-) metastásico, tras quimioterapia previa', 2, 'Trastuzumab deruxtecan 5,4 mg/kg IV c/21 d', '["trastuzumab deruxtecan"]'::jsonb, 'DESTINY-Breast04', 'fase_3', 'Modi S, et al. N Engl J Med 2022;387:9-20', 'https://doi.org/10.1056/NEJMoa2203690', 9.9, 23.4, 52.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + quimioterapia (TNBC CPS ≥10)', 'C50.9', 'Cáncer de mama triple negativo metastásico, PD-L1 CPS ≥10', 1, 'Pembrolizumab 200 mg IV c/21 d + quimioterapia a elección (nab-paclitaxel 100 mg/m² d1,8,15 c/28 d; paclitaxel 90 mg/m² d1,8,15; o gemcitabina 1000 + carboplatino AUC 2 d1,8 c/21 d)', '["pembrolizumab", "nab-paclitaxel", "paclitaxel", "gemcitabina", "carboplatino"]'::jsonb, 'KEYNOTE-355', 'fase_3', 'Cortes J, et al. N Engl J Med 2022;387:217-226 (SG final, CPS ≥10)', 'https://doi.org/10.1056/NEJMoa2202809', 9.7, 23.0, 53.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sacituzumab govitecan', 'C50.9', 'Cáncer de mama triple negativo metastásico, ≥2 líneas previas', 3, 'Sacituzumab govitecan 10 mg/kg IV días 1 y 8 c/21 d', '["sacituzumab govitecan"]'::jsonb, 'ASCENT', 'fase_3', 'Bardia A, et al. N Engl J Med 2021;384:1529-1541', 'https://doi.org/10.1056/NEJMoa2028485', 5.6, 12.1, 35.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Olaparib (BRCA germinal)', 'C50.9', 'Cáncer de mama HER2- metastásico con mutación germinal BRCA1/2, tras quimioterapia', 2, 'Olaparib 300 mg VO c/12 h continuo', '["olaparib"]'::jsonb, 'OlympiAD', 'fase_3', 'Robson M, et al. N Engl J Med 2017;377:523-533', 'https://doi.org/10.1056/NEJMoa1706450', 7.0, 19.3, 59.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Capecitabina adyuvante (enfermedad residual post-neoadyuvancia)', 'C50.9', 'Cáncer de mama triple negativo con enfermedad residual tras neoadyuvancia', NULL, 'Capecitabina 1250 mg/m² VO c/12 h, días 1-14 c/21 d, 6-8 ciclos', '["capecitabina"]'::jsonb, 'CREATE-X', 'fase_3', 'Masuda N, et al. N Engl J Med 2017;376:2147-2159 (SG 5 años 78,8% vs 70,3% en TNBC)', 'https://doi.org/10.1056/NEJMoa1612645', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + pemetrexed + platino', 'C34.9', 'CPCNP no escamoso metastásico, sin alteraciones EGFR/ALK', 1, 'Pembrolizumab 200 mg + pemetrexed 500 mg/m² + cisplatino 75 mg/m² o carboplatino AUC 5, IV c/21 d ×4 → mantenimiento pembrolizumab + pemetrexed', '["pembrolizumab", "pemetrexed", "cisplatino", "carboplatino"]'::jsonb, 'KEYNOTE-189', 'fase_3', 'Gandhi L, et al. N Engl J Med 2018;378:2078-2092', 'https://doi.org/10.1056/NEJMoa1801005', 8.8, 22.0, 47.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + carboplatino + paclitaxel (escamoso)', 'C34.9', 'CPCNP escamoso metastásico', 1, 'Pembrolizumab 200 mg + carboplatino AUC 6 + paclitaxel 200 mg/m² (o nab-paclitaxel 100 mg/m² d1,8,15), IV c/21 d ×4 → mantenimiento pembrolizumab', '["pembrolizumab", "carboplatino", "paclitaxel", "nab-paclitaxel"]'::jsonb, 'KEYNOTE-407', 'fase_3', 'Paz-Ares L, et al. N Engl J Med 2018;379:2040-2051', 'https://doi.org/10.1056/NEJMoa1810865', 6.4, 15.9, 57.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab monoterapia (PD-L1 ≥50%)', 'C34.9', 'CPCNP metastásico, PD-L1 TPS ≥50%, sin alteraciones EGFR/ALK', 1, 'Pembrolizumab 200 mg IV c/21 d (o 400 mg c/42 d) hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-024', 'fase_3', 'Reck M, et al. N Engl J Med 2016;375:1823-1833', 'https://doi.org/10.1056/NEJMoa1606774', 10.3, 26.3, 44.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Osimertinib', 'C34.9', 'CPCNP avanzado EGFR mutado (del19/L858R)', 1, 'Osimertinib 80 mg VO/d continuo', '["osimertinib"]'::jsonb, 'FLAURA', 'fase_3', 'Soria JC, et al. N Engl J Med 2018;378:113-125; SG: Ramalingam SS, et al. N Engl J Med 2020;382:41-50', 'https://doi.org/10.1056/NEJMoa1713137', 18.9, 38.6, 80.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Osimertinib + pemetrexed + platino', 'C34.9', 'CPCNP avanzado EGFR mutado, enfermedad de alto riesgo', 1, 'Osimertinib 80 mg VO/d + pemetrexed 500 mg/m² + cisplatino 75 mg/m² o carboplatino AUC 5 c/21 d ×4 → osimertinib + pemetrexed de mantenimiento', '["osimertinib", "pemetrexed", "cisplatino", "carboplatino"]'::jsonb, 'FLAURA2', 'fase_3', 'Planchard D, et al. N Engl J Med 2023;389:1935-1948', 'https://doi.org/10.1056/NEJMoa2306434', 25.5, NULL, 83.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Alectinib', 'C34.9', 'CPCNP avanzado ALK positivo', 1, 'Alectinib 600 mg VO c/12 h continuo', '["alectinib"]'::jsonb, 'ALEX', 'fase_3', 'Peters S, et al. N Engl J Med 2017;377:829-838', 'https://doi.org/10.1056/NEJMoa1704795', 34.8, NULL, 82.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lorlatinib', 'C34.9', 'CPCNP avanzado ALK positivo', 1, 'Lorlatinib 100 mg VO/d continuo', '["lorlatinib"]'::jsonb, 'CROWN', 'fase_3', 'Shaw AT, et al. N Engl J Med 2020;383:2018-2029 (SLP a 5 años 60%, mediana no alcanzada)', 'https://doi.org/10.1056/NEJMoa2027187', NULL, NULL, 76.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Durvalumab de consolidación post-quimiorradioterapia', 'C34.9', 'CPCNP estadio III irresecable, sin progresión tras quimiorradioterapia', NULL, 'Durvalumab 10 mg/kg IV c/14 d hasta 12 meses', '["durvalumab"]'::jsonb, 'PACIFIC', 'fase_3', 'Antonia SJ, et al. N Engl J Med 2017;377:1919-1929; 5 años: Spigel DR, et al. J Clin Oncol 2022;40:1301-1311', 'https://doi.org/10.1056/NEJMoa1709937', 16.8, 47.5, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Osimertinib adyuvante', 'C34.9', 'CPCNP EGFR mutado, estadio IB-IIIA resecado, adyuvancia', NULL, 'Osimertinib 80 mg VO/d por 3 años', '["osimertinib"]'::jsonb, 'ADAURA', 'fase_3', 'Wu YL, et al. N Engl J Med 2020;383:1711-1723; SG: Tsuboi M, et al. N Engl J Med 2023;389:137-147', 'https://doi.org/10.1056/NEJMoa2027071', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + quimioterapia neoadyuvante', 'C34.9', 'CPCNP resecable estadio IB-IIIA, neoadyuvancia', NULL, 'Nivolumab 360 mg + quimioterapia basada en platino IV c/21 d ×3 ciclos antes de cirugía', '["nivolumab", "carboplatino", "cisplatino", "paclitaxel", "pemetrexed"]'::jsonb, 'CheckMate 816', 'fase_3', 'Forde PM, et al. N Engl J Med 2022;386:1973-1985 (SLE 31,6 m vs 20,8 m; pCR 24% vs 2,2%)', 'https://doi.org/10.1056/NEJMoa2202170', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab', 'C34.9', 'CPCNP no escamoso metastásico, progresión a quimioterapia basada en platino', 2, 'Nivolumab 240 mg IV c/14 d (o 480 mg c/28 d)', '["nivolumab"]'::jsonb, 'CheckMate 057', 'fase_3', 'Borghaei H, et al. N Engl J Med 2015;373:1627-1639', 'https://doi.org/10.1056/NEJMoa1507643', 2.3, 12.2, 19.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Docetaxel + ramucirumab', 'C34.9', 'CPCNP metastásico, progresión a platino (± inmunoterapia)', 2, 'Docetaxel 75 mg/m² + ramucirumab 10 mg/kg IV c/21 d', '["docetaxel", "ramucirumab"]'::jsonb, 'REVEL', 'fase_3', 'Garon EB, et al. Lancet 2014;384:665-673', 'https://doi.org/10.1016/S0140-6736(14)60845-X', 4.5, 10.5, 23.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sotorasib (KRAS G12C)', 'C34.9', 'CPCNP avanzado KRAS G12C, progresión a platino e inmunoterapia', 2, 'Sotorasib 960 mg VO/d continuo', '["sotorasib"]'::jsonb, 'CodeBreaK 200', 'fase_3', 'de Langen AJ, et al. Lancet 2023;401:733-746', 'https://doi.org/10.1016/S0140-6736(23)00221-0', 5.6, NULL, 28.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino + etopósido + atezolizumab', 'C34.9', 'Cáncer de pulmón de célula pequeña, enfermedad extendida', 1, 'Carboplatino AUC 5 d1 + etopósido 100 mg/m² d1-3 + atezolizumab 1200 mg d1, IV c/21 d ×4 → mantenimiento atezolizumab', '["carboplatino", "etopósido", "atezolizumab"]'::jsonb, 'IMpower133', 'fase_3', 'Horn L, et al. N Engl J Med 2018;379:2220-2229', 'https://doi.org/10.1056/NEJMoa1809064', 5.2, 12.3, 60.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Platino + etopósido + durvalumab', 'C34.9', 'Cáncer de pulmón de célula pequeña, enfermedad extendida', 1, 'Durvalumab 1500 mg + cisplatino o carboplatino + etopósido IV c/21 d ×4 → mantenimiento durvalumab c/28 d', '["durvalumab", "cisplatino", "carboplatino", "etopósido"]'::jsonb, 'CASPIAN', 'fase_3', 'Paz-Ares L, et al. Lancet 2019;394:1929-1939', 'https://doi.org/10.1016/S0140-6736(19)32222-6', 5.1, 13.0, 68.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Durvalumab de consolidación (CPCP enfermedad limitada)', 'C34.9', 'Cáncer de pulmón de célula pequeña, enfermedad limitada, sin progresión tras quimiorradioterapia', NULL, 'Durvalumab 1500 mg IV c/28 d hasta 24 meses', '["durvalumab"]'::jsonb, 'ADRIATIC', 'fase_3', 'Cheng Y, et al. N Engl J Med 2024;391:1313-1327 (SG 55,9 m vs 33,4 m)', 'https://doi.org/10.1056/NEJMoa2404873', 16.6, 55.9, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFOX adyuvante', 'C18.9', 'Cáncer de colon estadio III (y II de alto riesgo) resecado, adyuvancia', NULL, 'Oxaliplatino 85 mg/m² + leucovorina 400 mg/m² + 5-FU 400 mg/m² bolo + 5-FU 2400 mg/m² infusión 46 h, c/14 d ×12 ciclos (6 meses)', '["oxaliplatino", "leucovorina", "fluorouracilo"]'::jsonb, 'MOSAIC', 'fase_3', 'André T, et al. N Engl J Med 2004;350:2343-2351', 'https://doi.org/10.1056/NEJMoa032709', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('CAPOX adyuvante (3 vs 6 meses)', 'C18.9', 'Cáncer de colon estadio III resecado, adyuvancia (3 meses en bajo riesgo T1-3 N1)', NULL, 'Capecitabina 1000 mg/m² VO c/12 h días 1-14 + oxaliplatino 130 mg/m² IV d1, c/21 d ×4 (3 meses) u ×8 (6 meses)', '["capecitabina", "oxaliplatino"]'::jsonb, 'IDEA', 'metanalisis', 'Grothey A, et al. N Engl J Med 2018;378:1177-1188 (análisis conjunto de 6 fase III)', 'https://doi.org/10.1056/NEJMoa1713709', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFOX o FOLFIRI + bevacizumab', 'C18.9', 'Cáncer colorrectal metastásico (RAS mutado o lado derecho)', 1, 'Bevacizumab 5 mg/kg IV c/14 d + mFOLFOX6 o FOLFIRI (irinotecán 180 mg/m² + LV 400 + 5-FU 400 bolo + 2400 en 46 h) c/14 d', '["bevacizumab", "oxaliplatino", "irinotecán", "leucovorina", "fluorouracilo"]'::jsonb, 'AVF2107 (Hurwitz)', 'fase_3', 'Hurwitz H, et al. N Engl J Med 2004;350:2335-2342', 'https://doi.org/10.1056/NEJMoa032691', 10.6, 20.3, 44.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFIRI + cetuximab (RAS/BRAF nativo, lado izquierdo)', 'C18.9', 'Cáncer colorrectal metastásico RAS nativo, tumor de colon izquierdo', 1, 'Cetuximab 400 mg/m² carga → 250 mg/m² semanal (o 500 mg/m² c/14 d) + FOLFIRI c/14 d', '["cetuximab", "irinotecán", "leucovorina", "fluorouracilo"]'::jsonb, 'CRYSTAL', 'fase_3', 'Van Cutsem E, et al. N Engl J Med 2009;360:1408-1417; análisis RAS nativo: J Clin Oncol 2015;33:692-700', 'https://doi.org/10.1056/NEJMoa0805019', 11.4, 28.4, 66.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('mFOLFOX6 + panitumumab (RAS nativo, lado izquierdo)', 'C18.9', 'Cáncer colorrectal metastásico RAS nativo, colon izquierdo', 1, 'Panitumumab 6 mg/kg IV c/14 d + mFOLFOX6 c/14 d', '["panitumumab", "oxaliplatino", "leucovorina", "fluorouracilo"]'::jsonb, 'PARADIGM', 'fase_3', 'Watanabe J, et al. JAMA 2023;329:1271-1282 (lado izquierdo: SG 37,9 m vs 34,3 m)', 'https://doi.org/10.1001/jama.2023.4428', NULL, 37.9, 80.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFOXIRI + bevacizumab', 'C18.9', 'Cáncer colorrectal metastásico, paciente apto, enfermedad agresiva o potencialmente resecable', 1, 'Irinotecán 165 mg/m² + oxaliplatino 85 mg/m² + leucovorina 200 mg/m² + 5-FU 3200 mg/m² infusión 48 h + bevacizumab 5 mg/kg, c/14 d ×12 → mantenimiento 5-FU/bev', '["irinotecán", "oxaliplatino", "leucovorina", "fluorouracilo", "bevacizumab"]'::jsonb, 'TRIBE', 'fase_3', 'Loupakis F, et al. N Engl J Med 2014;371:1609-1618', 'https://doi.org/10.1056/NEJMoa1403108', 12.1, 29.8, 65.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab (MSI-H/dMMR)', 'C18.9', 'Cáncer colorrectal metastásico MSI-H/dMMR', 1, 'Pembrolizumab 200 mg IV c/21 d hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-177', 'fase_3', 'André T, et al. N Engl J Med 2020;383:2207-2218 (SG final 77,5 m vs 36,7 m)', 'https://doi.org/10.1056/NEJMoa2017699', 16.5, 77.5, 45.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFIRI + aflibercept', 'C18.9', 'Cáncer colorrectal metastásico, progresión a esquema con oxaliplatino', 2, 'Aflibercept 4 mg/kg IV + FOLFIRI c/14 d', '["aflibercept", "irinotecán", "leucovorina", "fluorouracilo"]'::jsonb, 'VELOUR', 'fase_3', 'Van Cutsem E, et al. J Clin Oncol 2012;30:3499-3506', 'https://doi.org/10.1200/JCO.2012.42.8201', 6.9, 13.5, 19.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Encorafenib + cetuximab (BRAF V600E)', 'C18.9', 'Cáncer colorrectal metastásico BRAF V600E, tras ≥1 línea previa', 2, 'Encorafenib 300 mg VO/d + cetuximab 400→250 mg/m² semanal (o 500 mg/m² c/14 d)', '["encorafenib", "cetuximab"]'::jsonb, 'BEACON', 'fase_3', 'Kopetz S, et al. N Engl J Med 2019;381:1632-1643', 'https://doi.org/10.1056/NEJMoa1908075', 4.3, 9.3, 20.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trifluridina/tipiracilo + bevacizumab', 'C18.9', 'Cáncer colorrectal metastásico refractario (≥2 líneas previas)', 3, 'Trifluridina/tipiracilo 35 mg/m² VO c/12 h, días 1-5 y 8-12 c/28 d + bevacizumab 5 mg/kg IV días 1 y 15', '["trifluridina/tipiracilo", "bevacizumab"]'::jsonb, 'SUNLIGHT', 'fase_3', 'Prager GW, et al. N Engl J Med 2023;388:1657-1667', 'https://doi.org/10.1056/NEJMoa2214963', 5.6, 10.8, 6.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Regorafenib', 'C18.9', 'Cáncer colorrectal metastásico refractario', 3, 'Regorafenib 160 mg VO/d, días 1-21 c/28 d (considerar escalamiento 80→160 mg)', '["regorafenib"]'::jsonb, 'CORRECT', 'fase_3', 'Grothey A, et al. Lancet 2013;381:303-312', 'https://doi.org/10.1016/S0140-6736(12)61900-X', 1.9, 6.4, 1.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Capecitabina + radioterapia neoadyuvante (recto)', 'C20', 'Cáncer de recto localmente avanzado (T3-4 o N+), neoadyuvancia', NULL, 'Capecitabina 825 mg/m² VO c/12 h los días de radioterapia (50,4 Gy en 28 fracciones), cirugía TME a las 6-8 semanas', '["capecitabina"]'::jsonb, 'Hofheinz (fase III cape vs 5-FU)', 'fase_3', 'Hofheinz RD, et al. Lancet Oncol 2012;13:579-588', 'https://doi.org/10.1016/S1470-2045(12)70116-X', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Terapia neoadyuvante total: mFOLFIRINOX → quimiorradioterapia (recto)', 'C20', 'Cáncer de recto localmente avanzado cT3-4, terapia neoadyuvante total', NULL, 'mFOLFIRINOX (oxaliplatino 85 + irinotecán 180 + LV 400 + 5-FU 2400 en 46 h) c/14 d ×6 → quimiorradioterapia con capecitabina → cirugía TME', '["oxaliplatino", "irinotecán", "leucovorina", "fluorouracilo", "capecitabina"]'::jsonb, 'PRODIGE 23', 'fase_3', 'Conroy T, et al. Lancet Oncol 2021;22:702-715 (SLE 3 años 76% vs 69%)', 'https://doi.org/10.1016/S1470-2045(21)00079-6', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TDA + docetaxel', 'C61', 'Cáncer de próstata metastásico hormonosensible, alto volumen', 1, 'Docetaxel 75 mg/m² IV c/21 d ×6 + terapia de deprivación androgénica continua', '["docetaxel", "goserelina", "leuprolide"]'::jsonb, 'CHAARTED', 'fase_3', 'Sweeney CJ, et al. N Engl J Med 2015;373:737-746', 'https://doi.org/10.1056/NEJMoa1503747', NULL, 57.6, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TDA + abiraterona + prednisona', 'C61', 'Cáncer de próstata metastásico hormonosensible de alto riesgo', 1, 'Abiraterona 1000 mg VO/d + prednisona 5 mg VO/d + TDA continua', '["abiraterona", "prednisona", "goserelina", "leuprolide"]'::jsonb, 'LATITUDE', 'fase_3', 'Fizazi K, et al. N Engl J Med 2017;377:352-360; final: Lancet Oncol 2019;20:686-700', 'https://doi.org/10.1056/NEJMoa1704174', NULL, 53.3, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TDA + apalutamida', 'C61', 'Cáncer de próstata metastásico hormonosensible', 1, 'Apalutamida 240 mg VO/d + TDA continua', '["apalutamida", "goserelina", "leuprolide"]'::jsonb, 'TITAN', 'fase_3', 'Chi KN, et al. N Engl J Med 2019;381:13-24; SG final: J Clin Oncol 2021;39:2294-2303 (HR 0,65)', 'https://doi.org/10.1056/NEJMoa1903307', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TDA + enzalutamida', 'C61', 'Cáncer de próstata metastásico hormonosensible', 1, 'Enzalutamida 160 mg VO/d + TDA continua', '["enzalutamida", "goserelina", "leuprolide"]'::jsonb, 'ARCHES', 'fase_3', 'Armstrong AJ, et al. J Clin Oncol 2019;37:2974-2986', 'https://doi.org/10.1200/JCO.19.00799', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Triplete: TDA + docetaxel + darolutamida', 'C61', 'Cáncer de próstata metastásico hormonosensible, candidato a quimioterapia', 1, 'Darolutamida 600 mg VO c/12 h + docetaxel 75 mg/m² c/21 d ×6 + TDA continua', '["darolutamida", "docetaxel", "goserelina", "leuprolide"]'::jsonb, 'ARASENS', 'fase_3', 'Smith MR, et al. N Engl J Med 2022;386:1132-1142 (HR SG 0,68)', 'https://doi.org/10.1056/NEJMoa2119115', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Abiraterona + prednisona (CPRCm pre-quimioterapia)', 'C61', 'Cáncer de próstata resistente a castración metastásico, asintomático o poco sintomático', 1, 'Abiraterona 1000 mg VO/d + prednisona 5 mg VO c/12 h', '["abiraterona", "prednisona"]'::jsonb, 'COU-AA-302', 'fase_3', 'Ryan CJ, et al. Lancet Oncol 2015;16:152-160 (análisis final)', 'https://doi.org/10.1016/S1470-2045(14)71205-7', 16.5, 34.7, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Enzalutamida (CPRCm pre-quimioterapia)', 'C61', 'Cáncer de próstata resistente a castración metastásico', 1, 'Enzalutamida 160 mg VO/d continuo', '["enzalutamida"]'::jsonb, 'PREVAIL', 'fase_3', 'Beer TM, et al. N Engl J Med 2014;371:424-433', 'https://doi.org/10.1056/NEJMoa1405095', 20.0, 35.3, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Docetaxel + prednisona', 'C61', 'Cáncer de próstata resistente a castración metastásico', 1, 'Docetaxel 75 mg/m² IV c/21 d + prednisona 5 mg VO c/12 h, hasta 10 ciclos', '["docetaxel", "prednisona"]'::jsonb, 'TAX 327', 'fase_3', 'Tannock IF, et al. N Engl J Med 2004;351:1502-1512', 'https://doi.org/10.1056/NEJMoa040720', NULL, 19.2, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Cabazitaxel (post-docetaxel y post-ARTA)', 'C61', 'CPRCm con progresión a docetaxel y a un antiandrógeno de nueva generación', 3, 'Cabazitaxel 25 mg/m² IV c/21 d + prednisona 10 mg/d + G-CSF profiláctico', '["cabazitaxel", "prednisona", "filgrastim"]'::jsonb, 'CARD', 'fase_3', 'de Wit R, et al. N Engl J Med 2019;381:2506-2518', 'https://doi.org/10.1056/NEJMoa1911206', 8.0, 13.6, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Olaparib (HRR mutado)', 'C61', 'CPRCm con mutación BRCA1/2 o ATM, progresión a antiandrógeno de nueva generación', 2, 'Olaparib 300 mg VO c/12 h continuo', '["olaparib"]'::jsonb, 'PROfound', 'fase_3', 'de Bono J, et al. N Engl J Med 2020;382:2091-2102 (cohorte A)', 'https://doi.org/10.1056/NEJMoa1911440', 7.4, 19.1, 33.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lutecio-177-PSMA-617', 'C61', 'CPRCm PSMA positivo, progresión a ARTA y taxano', 3, '177Lu-PSMA-617 7,4 GBq IV c/6 semanas, hasta 6 ciclos', '["lutecio-177 vipivotida tetraxetán"]'::jsonb, 'VISION', 'fase_3', 'Sartor O, et al. N Engl J Med 2021;385:1091-1103', 'https://doi.org/10.1056/NEJMoa2107322', 8.7, 15.3, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Apalutamida (CPRC no metastásico)', 'C61', 'Cáncer de próstata resistente a castración no metastásico, PSA-DT ≤10 meses', 1, 'Apalutamida 240 mg VO/d + TDA continua', '["apalutamida"]'::jsonb, 'SPARTAN', 'fase_3', 'Smith MR, et al. N Engl J Med 2018;378:1408-1418 (SLM 40,5 m vs 16,2 m)', 'https://doi.org/10.1056/NEJMoa1715546', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FLOT perioperatorio', 'C16.9', 'Adenocarcinoma gástrico o de la unión gastroesofágica resecable ≥cT2 o cN+', NULL, 'Docetaxel 50 mg/m² + oxaliplatino 85 mg/m² + leucovorina 200 mg/m² + 5-FU 2600 mg/m² infusión 24 h, c/14 d: 4 ciclos preoperatorios y 4 posoperatorios', '["docetaxel", "oxaliplatino", "leucovorina", "fluorouracilo"]'::jsonb, 'FLOT4-AIO', 'fase_3', 'Al-Batran SE, et al. Lancet 2019;393:1948-1957 (SG 50 m vs 35 m)', 'https://doi.org/10.1016/S0140-6736(18)32557-1', NULL, 50.0, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + quimioterapia (FOLFOX/CAPOX)', 'C16.9', 'Adenocarcinoma gástrico/UGE/esófago avanzado HER2 negativo (beneficio mayor si PD-L1 CPS ≥5)', 1, 'Nivolumab 240 mg c/14 d (con FOLFOX) o 360 mg c/21 d (con CAPOX) + quimioterapia hasta progresión (nivolumab máx. 2 años)', '["nivolumab", "oxaliplatino", "capecitabina", "leucovorina", "fluorouracilo"]'::jsonb, 'CheckMate 649', 'fase_3', 'Janjigian YY, et al. Lancet 2021;398:27-40 (CPS ≥5: SG 14,4 m, SLP 7,7 m)', 'https://doi.org/10.1016/S0140-6736(21)00797-2', 7.7, 14.4, 60.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab + cisplatino + fluoropirimidina (HER2+)', 'C16.9', 'Adenocarcinoma gástrico/UGE avanzado HER2 positivo', 1, 'Trastuzumab 8 mg/kg carga → 6 mg/kg + cisplatino 80 mg/m² + capecitabina 1000 mg/m² c/12 h d1-14 (o 5-FU 800 mg/m²/d d1-5), c/21 d ×6 → trastuzumab hasta progresión', '["trastuzumab", "cisplatino", "capecitabina", "fluorouracilo"]'::jsonb, 'ToGA', 'fase_3', 'Bang YJ, et al. Lancet 2010;376:687-697', 'https://doi.org/10.1016/S0140-6736(10)61121-X', 6.7, 13.8, 47.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + trastuzumab + quimioterapia (HER2+)', 'C16.9', 'Adenocarcinoma gástrico/UGE avanzado HER2 positivo, PD-L1 CPS ≥1', 1, 'Pembrolizumab 200 mg c/21 d + trastuzumab + cisplatino/capecitabina o FOLFOX', '["pembrolizumab", "trastuzumab", "cisplatino", "capecitabina", "oxaliplatino", "fluorouracilo"]'::jsonb, 'KEYNOTE-811', 'fase_3', 'Janjigian YY, et al. Lancet 2023;402:2197-2208 (SLP 10,0 m vs 8,1 m)', 'https://doi.org/10.1016/S0140-6736(23)02033-0', 10.0, 20.0, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Ramucirumab + paclitaxel', 'C16.9', 'Adenocarcinoma gástrico/UGE avanzado, progresión a 1ª línea con platino y fluoropirimidina', 2, 'Ramucirumab 8 mg/kg IV días 1 y 15 + paclitaxel 80 mg/m² días 1, 8 y 15, c/28 d', '["ramucirumab", "paclitaxel"]'::jsonb, 'RAINBOW', 'fase_3', 'Wilke H, et al. Lancet Oncol 2014;15:1224-1235', 'https://doi.org/10.1016/S1470-2045(14)70420-6', 4.4, 9.6, 28.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trastuzumab deruxtecan (gástrico HER2+)', 'C16.9', 'Adenocarcinoma gástrico/UGE HER2 positivo, progresión a trastuzumab', 2, 'Trastuzumab deruxtecan 6,4 mg/kg IV c/21 d', '["trastuzumab deruxtecan"]'::jsonb, 'DESTINY-Gastric01', 'fase_2', 'Shitara K, et al. N Engl J Med 2020;382:2419-2430', 'https://doi.org/10.1056/NEJMoa2004413', 5.6, 12.5, 51.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trifluridina/tipiracilo', 'C16.9', 'Adenocarcinoma gástrico/UGE metastásico, ≥2 líneas previas', 3, 'Trifluridina/tipiracilo 35 mg/m² VO c/12 h, días 1-5 y 8-12 c/28 d', '["trifluridina/tipiracilo"]'::jsonb, 'TAGS', 'fase_3', 'Shitara K, et al. Lancet Oncol 2018;19:1437-1448', 'https://doi.org/10.1016/S1470-2045(18)30739-3', 2.0, 5.7, 4.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Atezolizumab + bevacizumab', 'C22.0', 'Carcinoma hepatocelular irresecable/avanzado, Child-Pugh A, sin várices de alto riesgo', 1, 'Atezolizumab 1200 mg + bevacizumab 15 mg/kg IV c/21 d (endoscopia previa obligatoria)', '["atezolizumab", "bevacizumab"]'::jsonb, 'IMbrave150', 'fase_3', 'Finn RS, et al. N Engl J Med 2020;382:1894-1905; actualización: Cheng AL, et al. J Hepatol 2022;76:862-873', 'https://doi.org/10.1056/NEJMoa1915745', 6.9, 19.2, 30.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Durvalumab + tremelimumab (STRIDE)', 'C22.0', 'Carcinoma hepatocelular irresecable, Child-Pugh A', 1, 'Tremelimumab 300 mg dosis única + durvalumab 1500 mg IV c/28 d hasta progresión', '["durvalumab", "tremelimumab"]'::jsonb, 'HIMALAYA', 'fase_3', 'Abou-Alfa GK, et al. NEJM Evid 2022;1(8):EVIDoa2100070', 'https://doi.org/10.1056/EVIDoa2100070', 3.8, 16.4, 20.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lenvatinib', 'C22.0', 'Carcinoma hepatocelular irresecable, Child-Pugh A', 1, 'Lenvatinib 12 mg/d VO (≥60 kg) u 8 mg/d (<60 kg) continuo', '["lenvatinib"]'::jsonb, 'REFLECT', 'fase_3', 'Kudo M, et al. Lancet 2018;391:1163-1173 (no inferioridad vs sorafenib)', 'https://doi.org/10.1016/S0140-6736(18)30207-1', 7.4, 13.6, 24.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sorafenib', 'C22.0', 'Carcinoma hepatocelular avanzado, Child-Pugh A', 1, 'Sorafenib 400 mg VO c/12 h continuo', '["sorafenib"]'::jsonb, 'SHARP', 'fase_3', 'Llovet JM, et al. N Engl J Med 2008;359:378-390', 'https://doi.org/10.1056/NEJMoa0708857', NULL, 10.7, 2.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Regorafenib', 'C22.0', 'Carcinoma hepatocelular con progresión a sorafenib (tolerancia previa)', 2, 'Regorafenib 160 mg VO/d, días 1-21 c/28 d', '["regorafenib"]'::jsonb, 'RESORCE', 'fase_3', 'Bruix J, et al. Lancet 2017;389:56-66', 'https://doi.org/10.1016/S0140-6736(16)32453-9', 3.1, 10.6, 11.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Cabozantinib', 'C22.0', 'Carcinoma hepatocelular avanzado, progresión a sorafenib', 2, 'Cabozantinib 60 mg VO/d continuo', '["cabozantinib"]'::jsonb, 'CELESTIAL', 'fase_3', 'Abou-Alfa GK, et al. N Engl J Med 2018;379:54-63', 'https://doi.org/10.1056/NEJMoa1717002', 5.2, 10.2, 4.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lenvatinib (CDT refractario a yodo)', 'C73', 'Cáncer diferenciado de tiroides refractario a yodo radiactivo, progresivo', 1, 'Lenvatinib 24 mg VO/d continuo', '["lenvatinib"]'::jsonb, 'SELECT', 'fase_3', 'Schlumberger M, et al. N Engl J Med 2015;372:621-630', 'https://doi.org/10.1056/NEJMoa1406470', 18.3, NULL, 64.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sorafenib (CDT refractario a yodo)', 'C73', 'Cáncer diferenciado de tiroides refractario a yodo radiactivo, progresivo', 1, 'Sorafenib 400 mg VO c/12 h continuo', '["sorafenib"]'::jsonb, 'DECISION', 'fase_3', 'Brose MS, et al. Lancet 2014;384:319-328', 'https://doi.org/10.1016/S0140-6736(14)60421-9', 10.8, NULL, 12.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Vandetanib (medular)', 'C73', 'Carcinoma medular de tiroides localmente avanzado o metastásico, progresivo o sintomático', 1, 'Vandetanib 300 mg VO/d continuo', '["vandetanib"]'::jsonb, 'ZETA', 'fase_3', 'Wells SA Jr, et al. J Clin Oncol 2012;30:134-141', 'https://doi.org/10.1200/JCO.2011.35.5040', 30.5, NULL, 45.0, true, NULL, true);
