INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dabrafenib + trametinib (anaplásico BRAF V600E)', 'C73', 'Carcinoma anaplásico de tiroides BRAF V600E, irresecable o metastásico', 1, 'Dabrafenib 150 mg VO c/12 h + trametinib 2 mg VO/d', '["dabrafenib", "trametinib"]'::jsonb, 'ROAR', 'fase_2', 'Subbiah V, et al. J Clin Oncol 2018;36:7-13', 'https://doi.org/10.1200/JCO.2017.73.6785', NULL, NULL, 56.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimiorradioterapia con cisplatino semanal', 'C53.9', 'Cáncer de cérvix localmente avanzado (FIGO IB3-IVA)', NULL, 'Cisplatino 40 mg/m² IV semanal ×5-6 concurrente con radioterapia pélvica externa + braquiterapia', '["cisplatino"]'::jsonb, 'GOG-120 (Rose)', 'fase_3', 'Rose PG, et al. N Engl J Med 1999;340:1144-1153', 'https://doi.org/10.1056/NEJM199904153401502', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimioterapia de inducción → quimiorradioterapia', 'C53.9', 'Cáncer de cérvix localmente avanzado (FIGO IB2-IVA)', NULL, 'Carboplatino AUC 2 + paclitaxel 80 mg/m² semanal ×6 → quimiorradioterapia estándar con cisplatino semanal', '["carboplatino", "paclitaxel", "cisplatino"]'::jsonb, 'INTERLACE', 'fase_3', 'McCormack M, et al. Lancet 2024;404:1525-1535 (SG 5 años 80% vs 72%)', 'https://doi.org/10.1016/S0140-6736(24)01438-7', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + quimiorradioterapia', 'C53.9', 'Cáncer de cérvix localmente avanzado de alto riesgo (FIGO 2014 III-IVA)', NULL, 'Pembrolizumab 200 mg c/21 d ×5 concurrente con quimiorradioterapia → pembrolizumab 400 mg c/6 sem ×15', '["pembrolizumab", "cisplatino"]'::jsonb, 'KEYNOTE-A18', 'fase_3', 'Lorusso D, et al. Lancet 2024;403:1341-1350', 'https://doi.org/10.1016/S0140-6736(24)00317-9', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + cisplatino/paclitaxel ± bevacizumab', 'C53.9', 'Cáncer de cérvix persistente, recurrente o metastásico, PD-L1 CPS ≥1', 1, 'Pembrolizumab 200 mg + paclitaxel 175 mg/m² + cisplatino 50 mg/m² (o carboplatino AUC 5) ± bevacizumab 15 mg/kg, IV c/21 d', '["pembrolizumab", "paclitaxel", "cisplatino", "carboplatino", "bevacizumab"]'::jsonb, 'KEYNOTE-826', 'fase_3', 'Colombo N, et al. N Engl J Med 2021;385:1856-1867', 'https://doi.org/10.1056/NEJMoa2112435', 10.4, 24.4, 65.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Cisplatino + paclitaxel + bevacizumab', 'C53.9', 'Cáncer de cérvix recurrente, persistente o metastásico', 1, 'Cisplatino 50 mg/m² + paclitaxel 135-175 mg/m² + bevacizumab 15 mg/kg, IV c/21 d', '["cisplatino", "paclitaxel", "bevacizumab"]'::jsonb, 'GOG-240', 'fase_3', 'Tewari KS, et al. N Engl J Med 2014;370:734-743', 'https://doi.org/10.1056/NEJMoa1309748', 8.2, 17.0, 48.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab monoterapia (2ª línea, CPS ≥1)', 'C53.9', 'Cáncer de cérvix recurrente/metastásico PD-L1 CPS ≥1, progresión a quimioterapia', 2, 'Pembrolizumab 200 mg IV c/21 d hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-158', 'fase_2', 'Chung HC, et al. J Clin Oncol 2019;37:1470-1478', 'https://doi.org/10.1200/JCO.18.01265', 2.1, 9.4, 14.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Tisotumab vedotin', 'C53.9', 'Cáncer de cérvix recurrente/metastásico, progresión a 1ª línea (2ª-3ª línea)', 2, 'Tisotumab vedotin 2 mg/kg IV c/21 d', '["tisotumab vedotin"]'::jsonb, 'innovaTV 301', 'fase_3', 'Vergote I, et al. N Engl J Med 2024;391:44-55', 'https://doi.org/10.1056/NEJMoa2313811', 4.2, 11.5, 17.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimioterapia neoadyuvante basada en cisplatino (ddMVAC o GC)', 'C67.9', 'Carcinoma urotelial músculo-invasivo (cT2-T4a), candidato a cistectomía', NULL, 'ddMVAC (metotrexato 30 + vinblastina 3 + doxorrubicina 30 + cisplatino 70 mg/m² c/14 d con G-CSF ×4-6) o gemcitabina 1000 d1,8 + cisplatino 70 c/21 d ×4', '["metotrexato", "vinblastina", "doxorrubicina", "cisplatino", "gemcitabina"]'::jsonb, 'SWOG-8710', 'fase_3', 'Grossman HB, et al. N Engl J Med 2003;349:859-866 (SG 77 m vs 46 m)', 'https://doi.org/10.1056/NEJMoa022148', NULL, 77.0, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Enfortumab vedotin + pembrolizumab', 'C67.9', 'Carcinoma urotelial localmente avanzado o metastásico', 1, 'Enfortumab vedotin 1,25 mg/kg IV días 1 y 8 + pembrolizumab 200 mg día 1, c/21 d', '["enfortumab vedotin", "pembrolizumab"]'::jsonb, 'EV-302', 'fase_3', 'Powles T, et al. N Engl J Med 2024;390:875-888', 'https://doi.org/10.1056/NEJMoa2312117', 12.5, 31.5, 67.7, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Gemcitabina + cisplatino', 'C67.9', 'Carcinoma urotelial avanzado o metastásico, apto para cisplatino', 1, 'Gemcitabina 1000 mg/m² días 1, 8 y 15 + cisplatino 70 mg/m² día 2, c/28 d (o esquema c/21 d días 1 y 8)', '["gemcitabina", "cisplatino"]'::jsonb, 'von der Maase', 'fase_3', 'von der Maase H, et al. J Clin Oncol 2000;18:3068-3077', 'https://doi.org/10.1200/JCO.2000.18.17.3068', 7.4, 13.8, 49.4, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Avelumab de mantenimiento', 'C67.9', 'Carcinoma urotelial avanzado sin progresión tras 4-6 ciclos de quimioterapia con platino', 1, 'Avelumab 800 mg IV c/14 d hasta progresión', '["avelumab"]'::jsonb, 'JAVELIN Bladder 100', 'fase_3', 'Powles T, et al. N Engl J Med 2020;383:1218-1230', 'https://doi.org/10.1056/NEJMoa2002788', 3.7, 21.4, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab (2ª línea)', 'C67.9', 'Carcinoma urotelial avanzado, progresión a quimioterapia con platino', 2, 'Pembrolizumab 200 mg IV c/21 d', '["pembrolizumab"]'::jsonb, 'KEYNOTE-045', 'fase_3', 'Bellmunt J, et al. N Engl J Med 2017;376:1015-1026', 'https://doi.org/10.1056/NEJMoa1613683', 2.1, 10.3, 21.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Enfortumab vedotin monoterapia', 'C67.9', 'Carcinoma urotelial avanzado, progresión a platino e inhibidor de checkpoint', 3, 'Enfortumab vedotin 1,25 mg/kg IV días 1, 8 y 15 c/28 d', '["enfortumab vedotin"]'::jsonb, 'EV-301', 'fase_3', 'Powles T, et al. N Engl J Med 2021;384:1125-1135', 'https://doi.org/10.1056/NEJMoa2035807', 5.6, 12.9, 40.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Erdafitinib (FGFR2/3 alterado)', 'C67.9', 'Carcinoma urotelial avanzado con alteración FGFR3/2, progresión a ≥1 línea incluida inmunoterapia', 2, 'Erdafitinib 8 mg VO/d (escalar a 9 mg según fosfatemia)', '["erdafitinib"]'::jsonb, 'THOR', 'fase_3', 'Loriot Y, et al. N Engl J Med 2023;389:1961-1971', 'https://doi.org/10.1056/NEJMoa2308849', 5.6, 12.1, 45.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab adyuvante', 'C67.9', 'Carcinoma urotelial músculo-invasivo de alto riesgo tras cirugía radical', NULL, 'Nivolumab 240 mg IV c/14 d hasta 1 año', '["nivolumab"]'::jsonb, 'CheckMate 274', 'fase_3', 'Bajorin DF, et al. N Engl J Med 2021;384:2102-2114 (SLE 20,8 m vs 10,8 m)', 'https://doi.org/10.1056/NEJMoa2034442', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('R-CHOP', 'C83.3', 'Linfoma difuso de células grandes B, 1ª línea', 1, 'Rituximab 375 mg/m² + ciclofosfamida 750 mg/m² + doxorrubicina 50 mg/m² + vincristina 1,4 mg/m² (máx. 2 mg) día 1 + prednisona 100 mg/d días 1-5, c/21 d ×6', '["rituximab", "ciclofosfamida", "doxorrubicina", "vincristina", "prednisona"]'::jsonb, 'GELA LNH-98.5', 'fase_3', 'Coiffier B, et al. N Engl J Med 2002;346:235-242', 'https://doi.org/10.1056/NEJMoa011795', NULL, NULL, 76.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pola-R-CHP', 'C83.3', 'Linfoma difuso de células grandes B, IPI 2-5, 1ª línea', 1, 'Polatuzumab vedotin 1,8 mg/kg + rituximab 375 mg/m² + ciclofosfamida 750 + doxorrubicina 50 + prednisona 100 mg d1-5, c/21 d ×6 + 2 ciclos de rituximab', '["polatuzumab vedotin", "rituximab", "ciclofosfamida", "doxorrubicina", "prednisona"]'::jsonb, 'POLARIX', 'fase_3', 'Tilly H, et al. N Engl J Med 2022;386:351-363 (SLP 2 años 76,7% vs 70,2%)', 'https://doi.org/10.1056/NEJMoa2115304', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('R-ICE o R-DHAP (rescate pre-trasplante)', 'C83.3', 'LDCGB recaído/refractario quimiosensible, candidato a TASPE', 2, 'R-ICE (rituximab + ifosfamida 5 g/m² + carboplatino AUC 5 + etopósido 100 mg/m² d1-3) o R-DHAP (rituximab + dexametasona 40 mg d1-4 + citarabina 2 g/m² ×2 d2 + cisplatino 100 mg/m²), c/21 d ×3 → TASPE', '["rituximab", "ifosfamida", "carboplatino", "etopósido", "dexametasona", "citarabina", "cisplatino"]'::jsonb, 'CORAL', 'fase_3', 'Gisselbrecht C, et al. J Clin Oncol 2010;28:4184-4190', 'https://doi.org/10.1200/JCO.2010.28.1618', NULL, NULL, 63.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Axicabtagén ciloleucel (CAR-T, 2ª línea)', 'C83.3', 'LDCGB refractario primario o recaída <12 meses', 2, 'Linfodepleción (fludarabina 30 mg/m² + ciclofosfamida 500 mg/m² ×3 d) → axicabtagén ciloleucel 2×10⁶ células CAR-T/kg, infusión única', '["axicabtagén ciloleucel", "fludarabina", "ciclofosfamida"]'::jsonb, 'ZUMA-7', 'fase_3', 'Locke FL, et al. N Engl J Med 2022;386:640-654 (SLE 8,3 m vs 2,0 m)', 'https://doi.org/10.1056/NEJMoa2116133', NULL, NULL, 83.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Bendamustina + rituximab (BR)', 'C82.9', 'Linfoma folicular (y otros indolentes) con alta carga tumoral, 1ª línea', 1, 'Bendamustina 90 mg/m² IV días 1-2 + rituximab 375 mg/m² día 1, c/28 d ×6', '["bendamustina", "rituximab"]'::jsonb, 'StiL NHL1', 'fase_3', 'Rummel MJ, et al. Lancet 2013;381:1203-1210', 'https://doi.org/10.1016/S0140-6736(12)61763-2', 69.5, NULL, 93.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Rituximab de mantenimiento', 'C82.9', 'Linfoma folicular con respuesta a inmunoquimioterapia de 1ª línea', 1, 'Rituximab 375 mg/m² IV c/8 semanas ×12 (2 años)', '["rituximab"]'::jsonb, 'PRIMA', 'fase_3', 'Salles G, et al. Lancet 2011;377:42-51 (SLP 10 años 51% vs 35%)', 'https://doi.org/10.1016/S0140-6736(10)62175-7', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lenalidomida + rituximab (R²)', 'C82.9', 'Linfoma folicular o de zona marginal recaído/refractario', 2, 'Lenalidomida 20 mg VO/d días 1-21 c/28 d ×12 ciclos + rituximab 375 mg/m² semanal ciclo 1, luego día 1 ciclos 2-5', '["lenalidomida", "rituximab"]'::jsonb, 'AUGMENT', 'fase_3', 'Leonard JP, et al. J Clin Oncol 2019;37:1188-1199', 'https://doi.org/10.1200/JCO.19.00010', 39.4, NULL, 78.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimiorradioterapia neoadyuvante CROSS', 'C15.9', 'Cáncer de esófago o unión gastroesofágica resecable (T1N1 o T2-3N0-1)', NULL, 'Carboplatino AUC 2 + paclitaxel 50 mg/m² IV semanal ×5 concurrente con radioterapia 41,4 Gy en 23 fracciones → esofagectomía', '["carboplatino", "paclitaxel"]'::jsonb, 'CROSS', 'fase_3', 'van Hagen P, et al. N Engl J Med 2012;366:2074-2084 (SG 49,4 m vs 24,0 m)', 'https://doi.org/10.1056/NEJMoa1112088', NULL, 49.4, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab adyuvante (enfermedad residual post-CROSS)', 'C15.9', 'Cáncer de esófago/UGE con enfermedad residual tras quimiorradioterapia neoadyuvante y cirugía R0', NULL, 'Nivolumab 240 mg IV c/14 d ×16 semanas, luego 480 mg c/28 d hasta completar 1 año', '["nivolumab"]'::jsonb, 'CheckMate 577', 'fase_3', 'Kelly RJ, et al. N Engl J Med 2021;384:1191-1203 (SLE 22,4 m vs 11,0 m)', 'https://doi.org/10.1056/NEJMoa2032125', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + cisplatino + 5-FU', 'C15.9', 'Cáncer de esófago avanzado (escamoso o adenocarcinoma) o UGE Siewert 1', 1, 'Pembrolizumab 200 mg + cisplatino 80 mg/m² d1 + 5-FU 800 mg/m²/d días 1-5, IV c/21 d', '["pembrolizumab", "cisplatino", "fluorouracilo"]'::jsonb, 'KEYNOTE-590', 'fase_3', 'Sun JM, et al. Lancet 2021;398:759-771', 'https://doi.org/10.1016/S0140-6736(21)01234-4', 6.3, 12.4, 45.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + quimioterapia (escamoso)', 'C15.9', 'Carcinoma escamocelular de esófago avanzado', 1, 'Nivolumab 240 mg c/14 d + cisplatino 80 mg/m² + 5-FU 800 mg/m²/d d1-5 c/28 d', '["nivolumab", "cisplatino", "fluorouracilo"]'::jsonb, 'CheckMate 648', 'fase_3', 'Doki Y, et al. N Engl J Med 2022;386:449-462', 'https://doi.org/10.1056/NEJMoa2111380', NULL, 13.2, 47.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('FOLFIRINOX', 'C25.9', 'Adenocarcinoma de páncreas metastásico, ECOG 0-1, bilirrubina normal', 1, 'Oxaliplatino 85 mg/m² + irinotecán 180 mg/m² + leucovorina 400 mg/m² + 5-FU 400 mg/m² bolo + 2400 mg/m² infusión 46 h, c/14 d', '["oxaliplatino", "irinotecán", "leucovorina", "fluorouracilo"]'::jsonb, 'PRODIGE 4/ACCORD 11', 'fase_3', 'Conroy T, et al. N Engl J Med 2011;364:1817-1825', 'https://doi.org/10.1056/NEJMoa1011923', 6.4, 11.1, 31.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Gemcitabina + nab-paclitaxel', 'C25.9', 'Adenocarcinoma de páncreas metastásico', 1, 'Nab-paclitaxel 125 mg/m² + gemcitabina 1000 mg/m² IV días 1, 8 y 15, c/28 d', '["nab-paclitaxel", "gemcitabina"]'::jsonb, 'MPACT', 'fase_3', 'Von Hoff DD, et al. N Engl J Med 2013;369:1691-1703', 'https://doi.org/10.1056/NEJMoa1304369', 5.5, 8.5, 23.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('mFOLFIRINOX adyuvante', 'C25.9', 'Adenocarcinoma de páncreas resecado R0/R1, ECOG 0-1, adyuvancia', NULL, 'Oxaliplatino 85 mg/m² + irinotecán 150 mg/m² + leucovorina 400 mg/m² + 5-FU 2400 mg/m² infusión 46 h (sin bolo), c/14 d ×12', '["oxaliplatino", "irinotecán", "leucovorina", "fluorouracilo"]'::jsonb, 'PRODIGE 24', 'fase_3', 'Conroy T, et al. N Engl J Med 2018;379:2395-2406 (SLE 21,6 m; SG 54,4 m)', 'https://doi.org/10.1056/NEJMoa1809775', NULL, 54.4, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Gemcitabina adyuvante', 'C25.9', 'Adenocarcinoma de páncreas resecado, no candidato a mFOLFIRINOX', NULL, 'Gemcitabina 1000 mg/m² IV días 1, 8 y 15, c/28 d ×6', '["gemcitabina"]'::jsonb, 'CONKO-001', 'fase_3', 'Oettle H, et al. JAMA 2013;310:1473-1481', 'https://doi.org/10.1001/jama.2013.279201', NULL, 22.8, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Irinotecán liposomal (nal-IRI) + 5-FU/LV', 'C25.9', 'Adenocarcinoma de páncreas metastásico, progresión a gemcitabina', 2, 'Irinotecán liposomal 70 mg/m² + leucovorina 400 mg/m² + 5-FU 2400 mg/m² infusión 46 h, c/14 d', '["irinotecán liposomal", "leucovorina", "fluorouracilo"]'::jsonb, 'NAPOLI-1', 'fase_3', 'Wang-Gillam A, et al. Lancet 2016;387:545-557', 'https://doi.org/10.1016/S0140-6736(15)00986-1', 3.1, 6.1, 16.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Olaparib de mantenimiento (BRCA germinal)', 'C25.9', 'Adenocarcinoma de páncreas metastásico gBRCA+, sin progresión tras ≥16 sem de platino', 1, 'Olaparib 300 mg VO c/12 h hasta progresión', '["olaparib"]'::jsonb, 'POLO', 'fase_3', 'Golan T, et al. N Engl J Med 2019;381:317-327', 'https://doi.org/10.1056/NEJMoa1903387', 7.4, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + axitinib', 'C64', 'Carcinoma de células renales de células claras avanzado', 1, 'Pembrolizumab 200 mg IV c/21 d + axitinib 5 mg VO c/12 h', '["pembrolizumab", "axitinib"]'::jsonb, 'KEYNOTE-426', 'fase_3', 'Rini BI, et al. N Engl J Med 2019;380:1116-1127', 'https://doi.org/10.1056/NEJMoa1816714', 15.7, 45.7, 60.4, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + cabozantinib', 'C64', 'Carcinoma de células renales avanzado', 1, 'Nivolumab 240 mg IV c/14 d + cabozantinib 40 mg VO/d', '["nivolumab", "cabozantinib"]'::jsonb, 'CheckMate 9ER', 'fase_3', 'Choueiri TK, et al. N Engl J Med 2021;384:829-841', 'https://doi.org/10.1056/NEJMoa2026982', 16.6, 37.7, 55.7, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + lenvatinib', 'C64', 'Carcinoma de células renales avanzado', 1, 'Pembrolizumab 200 mg IV c/21 d + lenvatinib 20 mg VO/d', '["pembrolizumab", "lenvatinib"]'::jsonb, 'CLEAR', 'fase_3', 'Motzer R, et al. N Engl J Med 2021;384:1289-1300', 'https://doi.org/10.1056/NEJMoa2035716', 23.9, 53.7, 71.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + ipilimumab (riesgo intermedio/pobre)', 'C64', 'Carcinoma de células renales avanzado, riesgo IMDC intermedio o pobre', 1, 'Nivolumab 3 mg/kg + ipilimumab 1 mg/kg IV c/21 d ×4 → nivolumab 480 mg c/28 d', '["nivolumab", "ipilimumab"]'::jsonb, 'CheckMate 214', 'fase_3', 'Motzer RJ, et al. N Engl J Med 2018;378:1277-1290 (SG final 47,0 m int/pobre)', 'https://doi.org/10.1056/NEJMoa1712126', 11.6, 47.0, 42.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sunitinib', 'C64', 'Carcinoma de células renales avanzado, alternativa si no hay acceso a inmunoterapia', 1, 'Sunitinib 50 mg VO/d, 4 semanas sí / 2 no', '["sunitinib"]'::jsonb, 'Motzer 2007', 'fase_3', 'Motzer RJ, et al. N Engl J Med 2007;356:115-124', 'https://doi.org/10.1056/NEJMoa065044', 11.0, 26.4, 47.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Cabozantinib (2ª línea)', 'C64', 'Carcinoma de células renales avanzado, progresión a terapia antiangiogénica', 2, 'Cabozantinib 60 mg VO/d continuo', '["cabozantinib"]'::jsonb, 'METEOR', 'fase_3', 'Choueiri TK, et al. Lancet Oncol 2016;17:917-927', 'https://doi.org/10.1016/S1470-2045(16)30107-3', 7.4, 21.4, 17.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab (2ª línea)', 'C64', 'Carcinoma de células renales avanzado, progresión a antiangiogénico', 2, 'Nivolumab 240 mg IV c/14 d (o 480 mg c/28 d)', '["nivolumab"]'::jsonb, 'CheckMate 025', 'fase_3', 'Motzer RJ, et al. N Engl J Med 2015;373:1803-1813', 'https://doi.org/10.1056/NEJMoa1510665', 4.6, 25.0, 25.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab adyuvante', 'C64', 'Carcinoma renal de células claras resecado de alto riesgo de recaída', NULL, 'Pembrolizumab 200 mg IV c/21 d ×17 ciclos (≈1 año)', '["pembrolizumab"]'::jsonb, 'KEYNOTE-564', 'fase_3', 'Choueiri TK, et al. N Engl J Med 2021;385:683-694; SG: N Engl J Med 2024;390:1359-1371 (HR 0,62)', 'https://doi.org/10.1056/NEJMoa2106391', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Imatinib', 'C92.1', 'Leucemia mieloide crónica en fase crónica', 1, 'Imatinib 400 mg VO/d continuo; monitoreo BCR::ABL1 por PCR cuantitativa c/3 meses', '["imatinib"]'::jsonb, 'IRIS', 'fase_3', 'Hochhaus A, et al. N Engl J Med 2017;376:917-927 (SG 10 años 83,3%)', 'https://doi.org/10.1056/NEJMoa1609324', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nilotinib', 'C92.1', 'Leucemia mieloide crónica en fase crónica (1ª línea o intolerancia/resistencia a imatinib)', 1, 'Nilotinib 300 mg VO c/12 h en ayunas (400 mg c/12 h en 2ª línea)', '["nilotinib"]'::jsonb, 'ENESTnd', 'fase_3', 'Saglio G, et al. N Engl J Med 2010;362:2251-2259', 'https://doi.org/10.1056/NEJMoa0912614', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dasatinib', 'C92.1', 'Leucemia mieloide crónica en fase crónica (1ª línea o resistencia a imatinib)', 1, 'Dasatinib 100 mg VO/d continuo', '["dasatinib"]'::jsonb, 'DASISION', 'fase_3', 'Kantarjian H, et al. N Engl J Med 2010;362:2260-2270', 'https://doi.org/10.1056/NEJMoa1002315', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Venetoclax + obinutuzumab (duración fija)', 'C91.1', 'Leucemia linfocítica crónica, 1ª línea (incluye comorbilidades)', 1, 'Obinutuzumab 1000 mg IV (d1-2, 8, 15 ciclo 1, luego d1) ×6 ciclos + venetoclax escalamiento 20→400 mg VO/d desde d22 del ciclo 1, total 12 ciclos de venetoclax', '["venetoclax", "obinutuzumab"]'::jsonb, 'CLL14', 'fase_3', 'Fischer K, et al. N Engl J Med 2019;380:2225-2236 (SLP mediana 76,2 m, seguimiento a 6 años)', 'https://doi.org/10.1056/NEJMoa1815281', 76.2, NULL, 85.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Acalabrutinib ± obinutuzumab', 'C91.1', 'Leucemia linfocítica crónica, 1ª línea', 1, 'Acalabrutinib 100 mg VO c/12 h continuo hasta progresión ± obinutuzumab ×6 ciclos', '["acalabrutinib", "obinutuzumab"]'::jsonb, 'ELEVATE-TN', 'fase_3', 'Sharman JP, et al. Lancet 2020;395:1278-1291 (SLP mediana no alcanzada)', 'https://doi.org/10.1016/S0140-6736(20)30262-2', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Ibrutinib', 'C91.1', 'Leucemia linfocítica crónica, 1ª línea en adulto mayor o del17p', 1, 'Ibrutinib 420 mg VO/d continuo hasta progresión', '["ibrutinib"]'::jsonb, 'RESONATE-2', 'fase_3', 'Burger JA, et al. N Engl J Med 2015;373:2425-2437', 'https://doi.org/10.1056/NEJMoa1509388', NULL, NULL, 86.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Venetoclax + rituximab (recaída)', 'C91.1', 'Leucemia linfocítica crónica recaída/refractaria', 2, 'Venetoclax escalamiento → 400 mg VO/d ×24 meses + rituximab 375→500 mg/m² mensual ×6', '["venetoclax", "rituximab"]'::jsonb, 'MURANO', 'fase_3', 'Seymour JF, et al. N Engl J Med 2018;378:1107-1120 (SLP 53,6 m vs 17,0 m)', 'https://doi.org/10.1056/NEJMoa1713976', 53.6, NULL, 92.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Inducción 7+3 (citarabina + daunorrubicina)', 'C92.0', 'Leucemia mieloide aguda, paciente apto para quimioterapia intensiva', 1, 'Citarabina 100-200 mg/m²/d infusión continua días 1-7 + daunorrubicina 60-90 mg/m²/d días 1-3; consolidación con citarabina altas dosis', '["citarabina", "daunorrubicina"]'::jsonb, 'ECOG E1900', 'fase_3', 'Fernandez HF, et al. N Engl J Med 2009;361:1249-1259 (daunorrubicina 90 vs 45: SG 23,7 vs 15,7 m)', 'https://doi.org/10.1056/NEJMoa0904544', NULL, 23.7, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('7+3 + midostaurina (FLT3 mutado)', 'C92.0', 'Leucemia mieloide aguda FLT3 mutada (ITD o TKD), paciente apto', 1, '7+3 estándar + midostaurina 50 mg VO c/12 h días 8-21 de inducción y consolidación, luego mantenimiento ×12 meses', '["citarabina", "daunorrubicina", "midostaurina"]'::jsonb, 'RATIFY', 'fase_3', 'Stone RM, et al. N Engl J Med 2017;377:454-464 (SG 74,7 m vs 25,6 m)', 'https://doi.org/10.1056/NEJMoa1614359', NULL, 74.7, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Venetoclax + azacitidina', 'C92.0', 'Leucemia mieloide aguda, no candidato a quimioterapia intensiva', 1, 'Azacitidina 75 mg/m² SC/IV días 1-7 c/28 d + venetoclax escalamiento → 400 mg VO/d (ajustar con azoles)', '["venetoclax", "azacitidina"]'::jsonb, 'VIALE-A', 'fase_3', 'DiNardo CD, et al. N Engl J Med 2020;383:617-629 (RC+RCi 66,4%)', 'https://doi.org/10.1056/NEJMoa2012971', NULL, 14.7, 66.4, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('ATRA + trióxido de arsénico', 'C92.4', 'Leucemia promielocítica aguda de riesgo bajo-intermedio (leucocitos ≤10×10⁹/L)', 1, 'Tretinoína (ATRA) 45 mg/m²/d VO + trióxido de arsénico 0,15 mg/kg/d IV hasta RC; consolidación ATO ×4 ciclos + ATRA ×7 ciclos', '["tretinoína", "trióxido de arsénico"]'::jsonb, 'APL0406', 'fase_3', 'Lo-Coco F, et al. N Engl J Med 2013;369:111-121 (SG 2 años 99%)', 'https://doi.org/10.1056/NEJMoa1300874', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Blinatumomab', 'C91.0', 'Leucemia linfoblástica aguda B recaída/refractaria Ph-negativa', 2, 'Blinatumomab 9 µg/d días 1-7 → 28 µg/d infusión continua hasta día 28, c/42 d; hasta 5 ciclos', '["blinatumomab"]'::jsonb, 'TOWER', 'fase_3', 'Kantarjian H, et al. N Engl J Med 2017;376:836-847', 'https://doi.org/10.1056/NEJMoa1609783', NULL, 7.7, 44.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Inotuzumab ozogamicina', 'C91.0', 'Leucemia linfoblástica aguda B CD22+ recaída/refractaria', 2, 'Inotuzumab 0,8 mg/m² día 1 + 0,5 mg/m² días 8 y 15, c/21-28 d', '["inotuzumab ozogamicina"]'::jsonb, 'INO-VATE', 'fase_3', 'Kantarjian HM, et al. N Engl J Med 2016;375:740-753 (RC/RCi 80,7%)', 'https://doi.org/10.1056/NEJMoa1509277', 5.0, 7.7, 80.7, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino + paclitaxel', 'C54.1', 'Cáncer de endometrio avanzado (estadio III-IV) o recurrente', 1, 'Carboplatino AUC 6 + paclitaxel 175 mg/m² IV c/21 d ×6', '["carboplatino", "paclitaxel"]'::jsonb, 'GOG-209', 'fase_3', 'Miller DS, et al. J Clin Oncol 2020;38:3841-3850 (no inferior a TAP; SG 37 m)', 'https://doi.org/10.1200/JCO.20.01076', 13.0, 37.0, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dostarlimab + carboplatino/paclitaxel', 'C54.1', 'Cáncer de endometrio primario avanzado o recurrente (mayor beneficio en dMMR/MSI-H)', 1, 'Dostarlimab 500 mg IV c/21 d ×6 con carboplatino AUC 5 + paclitaxel 175 mg/m² → dostarlimab 1000 mg c/6 sem hasta 3 años', '["dostarlimab", "carboplatino", "paclitaxel"]'::jsonb, 'RUBY', 'fase_3', 'Mirza MR, et al. N Engl J Med 2023;388:2145-2158 (dMMR: SLP 24 m 61,4% vs 15,7%)', 'https://doi.org/10.1056/NEJMoa2216334', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + carboplatino/paclitaxel', 'C54.1', 'Cáncer de endometrio avanzado o recurrente', 1, 'Pembrolizumab 200 mg IV c/21 d ×6 con carboplatino/paclitaxel → pembrolizumab 400 mg c/6 sem hasta 14 ciclos', '["pembrolizumab", "carboplatino", "paclitaxel"]'::jsonb, 'NRG-GY018', 'fase_3', 'Eskander RN, et al. N Engl J Med 2023;388:2159-2170', 'https://doi.org/10.1056/NEJMoa2302312', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lenvatinib + pembrolizumab (pMMR)', 'C54.1', 'Cáncer de endometrio avanzado pMMR, progresión a platino', 2, 'Lenvatinib 20 mg VO/d + pembrolizumab 200 mg IV c/21 d', '["lenvatinib", "pembrolizumab"]'::jsonb, 'KEYNOTE-775', 'fase_3', 'Makker V, et al. N Engl J Med 2022;386:437-448', 'https://doi.org/10.1056/NEJMoa2108330', 6.6, 17.4, 30.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab monoterapia (dMMR/MSI-H)', 'C54.1', 'Cáncer de endometrio dMMR/MSI-H avanzado, progresión a tratamiento previo', 2, 'Pembrolizumab 200 mg IV c/21 d hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-158', 'fase_2', 'O''Malley DM, et al. J Clin Oncol 2022;40:752-761', 'https://doi.org/10.1200/JCO.21.01874', 13.1, NULL, 48.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + ipilimumab', 'C43.9', 'Melanoma avanzado o metastásico irresecable', 1, 'Nivolumab 1 mg/kg + ipilimumab 3 mg/kg IV c/21 d ×4 → nivolumab 480 mg c/28 d', '["nivolumab", "ipilimumab"]'::jsonb, 'CheckMate 067', 'fase_3', 'Wolchok JD, et al. J Clin Oncol 2022;40:127-137 (seguimiento 6,5 años: SG 72,1 m)', 'https://doi.org/10.1200/JCO.21.02229', 11.5, 72.1, 58.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab', 'C43.9', 'Melanoma avanzado o metastásico irresecable', 1, 'Pembrolizumab 200 mg IV c/21 d (o 400 mg c/42 d) hasta 2 años', '["pembrolizumab"]'::jsonb, 'KEYNOTE-006', 'fase_3', 'Robert C, et al. Lancet Oncol 2019;20:1239-1251', 'https://doi.org/10.1016/S1470-2045(19)30388-2', 8.4, 32.7, 36.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab monoterapia', 'C43.9', 'Melanoma avanzado o metastásico irresecable', 1, 'Nivolumab 240 mg IV c/14 d o 480 mg c/28 d', '["nivolumab"]'::jsonb, 'CheckMate 066', 'fase_3', 'Robert C, et al. N Engl J Med 2015;372:320-330', 'https://doi.org/10.1056/NEJMoa1412082', 5.1, 37.5, 40.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dabrafenib + trametinib (BRAF V600)', 'C43.9', 'Melanoma avanzado BRAF V600E/K mutado', 1, 'Dabrafenib 150 mg VO c/12 h + trametinib 2 mg VO/d', '["dabrafenib", "trametinib"]'::jsonb, 'COMBI-d/COMBI-v', 'fase_3', 'Robert C, et al. N Engl J Med 2019;381:626-636 (análisis conjunto 5 años)', 'https://doi.org/10.1056/NEJMoa1904059', 11.1, 25.9, 68.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Encorafenib + binimetinib (BRAF V600)', 'C43.9', 'Melanoma avanzado BRAF V600 mutado', 1, 'Encorafenib 450 mg VO/d + binimetinib 45 mg VO c/12 h', '["encorafenib", "binimetinib"]'::jsonb, 'COLUMBUS', 'fase_3', 'Dummer R, et al. Lancet Oncol 2018;19:603-615; SG: Lancet Oncol 2018;19:1315-1327', 'https://doi.org/10.1016/S1470-2045(18)30497-2', 14.9, 33.6, 64.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab adyuvante', 'C43.9', 'Melanoma estadio III resecado, adyuvancia', NULL, 'Pembrolizumab 200 mg IV c/21 d ×18 ciclos (1 año)', '["pembrolizumab"]'::jsonb, 'KEYNOTE-054', 'fase_3', 'Eggermont AMM, et al. N Engl J Med 2018;378:1789-1801 (SLR 5 años 55,4% vs 38,3%)', 'https://doi.org/10.1056/NEJMoa1802357', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab adyuvante', 'C43.9', 'Melanoma estadio IIIB-IV resecado, adyuvancia', NULL, 'Nivolumab 480 mg IV c/28 d hasta 1 año', '["nivolumab"]'::jsonb, 'CheckMate 238', 'fase_3', 'Weber J, et al. N Engl J Med 2017;377:1824-1835 (HR recaída 0,65 vs ipilimumab)', 'https://doi.org/10.1056/NEJMoa1709030', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dabrafenib + trametinib adyuvante (BRAF V600)', 'C43.9', 'Melanoma estadio III BRAF V600E/K resecado, adyuvancia', NULL, 'Dabrafenib 150 mg c/12 h + trametinib 2 mg/d VO ×12 meses', '["dabrafenib", "trametinib"]'::jsonb, 'COMBI-AD', 'fase_3', 'Long GV, et al. N Engl J Med 2017;377:1813-1823 (HR recaída 0,47)', 'https://doi.org/10.1056/NEJMoa1708539', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino + paclitaxel', 'C56', 'Cáncer epitelial de ovario avanzado (estadio II-IV), tras citorreducción o neoadyuvancia', 1, 'Carboplatino AUC 5-6 + paclitaxel 175 mg/m² IV c/21 d ×6', '["carboplatino", "paclitaxel"]'::jsonb, 'GOG-158', 'fase_3', 'Ozols RF, et al. J Clin Oncol 2003;21:3194-3200', 'https://doi.org/10.1200/JCO.2003.02.153', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino + paclitaxel + bevacizumab → bevacizumab', 'C56', 'Cáncer de ovario avanzado estadio III-IV de alto riesgo', 1, 'Carboplatino AUC 6 + paclitaxel 175 mg/m² + bevacizumab 15 mg/kg IV c/21 d ×6 → bevacizumab de mantenimiento hasta 15-22 ciclos', '["carboplatino", "paclitaxel", "bevacizumab"]'::jsonb, 'GOG-218', 'fase_3', 'Burger RA, et al. N Engl J Med 2011;365:2473-2483', 'https://doi.org/10.1056/NEJMoa1104390', 14.1, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Olaparib de mantenimiento 1ª línea (BRCA mutado)', 'C56', 'Cáncer de ovario avanzado BRCA1/2 mutado, respuesta a platino de 1ª línea', 1, 'Olaparib 300 mg VO c/12 h ×2 años', '["olaparib"]'::jsonb, 'SOLO-1', 'fase_3', 'Moore K, et al. N Engl J Med 2018;379:2495-2505 (SLP mediana 56,0 m; SG 7 años 67%)', 'https://doi.org/10.1056/NEJMoa1810858', 56.0, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Niraparib de mantenimiento 1ª línea', 'C56', 'Cáncer de ovario avanzado con respuesta a platino de 1ª línea, independiente de biomarcador', 1, 'Niraparib 200-300 mg VO/d (dosis individualizada por peso/plaquetas) ×3 años', '["niraparib"]'::jsonb, 'PRIMA', 'fase_3', 'González-Martín A, et al. N Engl J Med 2019;381:2391-2402', 'https://doi.org/10.1056/NEJMoa1910962', 13.8, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Olaparib + bevacizumab de mantenimiento (HRD positivo)', 'C56', 'Cáncer de ovario avanzado HRD positivo, respuesta a platino + bevacizumab de 1ª línea', 1, 'Olaparib 300 mg VO c/12 h ×2 años + bevacizumab 15 mg/kg c/21 d hasta 15 meses', '["olaparib", "bevacizumab"]'::jsonb, 'PAOLA-1', 'fase_3', 'Ray-Coquard I, et al. N Engl J Med 2019;381:2416-2428 (HRD+: SLP 37,2 m)', 'https://doi.org/10.1056/NEJMoa1911361', 37.2, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino + gemcitabina + bevacizumab (recaída platino-sensible)', 'C56', 'Cáncer de ovario recurrente platino-sensible (>6 meses)', 2, 'Carboplatino AUC 4 d1 + gemcitabina 1000 mg/m² d1 y 8 + bevacizumab 15 mg/kg d1, c/21 d ×6-10 → bevacizumab hasta progresión', '["carboplatino", "gemcitabina", "bevacizumab"]'::jsonb, 'OCEANS', 'fase_3', 'Aghajanian C, et al. J Clin Oncol 2012;30:2039-2045', 'https://doi.org/10.1200/JCO.2012.42.0505', 12.4, NULL, 78.5, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimioterapia + bevacizumab (platino-resistente)', 'C56', 'Cáncer de ovario recurrente platino-resistente (<6 meses)', 2, 'Paclitaxel 80 mg/m² semanal, o doxorrubicina liposomal pegilada 40 mg/m² c/28 d, o topotecán + bevacizumab 10 mg/kg c/14 d', '["paclitaxel", "doxorrubicina liposomal pegilada", "topotecán", "bevacizumab"]'::jsonb, 'AURELIA', 'fase_3', 'Pujade-Lauraine E, et al. J Clin Oncol 2014;32:1302-1308', 'https://doi.org/10.1200/JCO.2013.51.4489', 6.7, NULL, 27.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Mirvetuximab soravtansina (FRα alto, platino-resistente)', 'C56', 'Cáncer de ovario platino-resistente con expresión alta de receptor de folato α', 2, 'Mirvetuximab soravtansina 6 mg/kg (peso corporal ajustado) IV c/21 d', '["mirvetuximab soravtansina"]'::jsonb, 'MIRASOL', 'fase_3', 'Moore KN, et al. N Engl J Med 2023;389:2162-2174', 'https://doi.org/10.1056/NEJMoa2309169', 5.6, 16.5, 42.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Radioterapia + temozolomida concurrente y adyuvante (protocolo Stupp)', 'C71.9', 'Glioblastoma de nuevo diagnóstico, ≤70 años, KPS ≥60', 1, 'Temozolomida 75 mg/m²/d VO durante radioterapia (60 Gy/30 fx) → temozolomida 150-200 mg/m²/d días 1-5 c/28 d ×6 ciclos', '["temozolomida"]'::jsonb, 'EORTC-NCIC (Stupp)', 'fase_3', 'Stupp R, et al. N Engl J Med 2005;352:987-996', 'https://doi.org/10.1056/NEJMoa043330', 6.9, 14.6, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Radioterapia hipofraccionada + temozolomida (adulto mayor)', 'C71.9', 'Glioblastoma en ≥65 años, candidato a tratamiento abreviado', 1, 'Radioterapia 40 Gy en 15 fracciones + temozolomida concurrente 75 mg/m²/d → temozolomida adyuvante ×12 ciclos', '["temozolomida"]'::jsonb, 'CCTG CE.6/EORTC 26062', 'fase_3', 'Perry JR, et al. N Engl J Med 2017;376:1027-1037', 'https://doi.org/10.1056/NEJMoa1611977', NULL, 9.3, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Bevacizumab (recurrencia)', 'C71.9', 'Glioblastoma recurrente', 2, 'Bevacizumab 10 mg/kg IV c/14 d, solo o con irinotecán', '["bevacizumab", "irinotecán"]'::jsonb, 'BRAIN (AVF3708g)', 'fase_2', 'Friedman HS, et al. J Clin Oncol 2009;27:4733-4740', 'https://doi.org/10.1200/JCO.2008.19.8721', 4.2, 9.2, 28.2, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lomustina (recurrencia)', 'C71.9', 'Glioblastoma recurrente', 2, 'Lomustina 110 mg/m² VO c/6 semanas', '["lomustina"]'::jsonb, 'EORTC 26101', 'fase_3', 'Wick W, et al. N Engl J Med 2017;377:1954-1963', 'https://doi.org/10.1056/NEJMoa1707358', 1.5, 8.6, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Quimiorradioterapia con cisplatino (definitiva o adyuvante)', 'C14.8', 'Carcinoma escamocelular de cabeza y cuello localmente avanzado', NULL, 'Cisplatino 100 mg/m² IV c/21 d ×3 concurrente con radioterapia 70 Gy (definitiva) o 60-66 Gy (adyuvante por R1/extensión extracapsular)', '["cisplatino"]'::jsonb, 'MACH-NC', 'metanalisis', 'Pignon JP, et al. Radiother Oncol 2009;92:4-14 (beneficio absoluto SG 6,5% a 5 años)', 'https://doi.org/10.1016/j.radonc.2009.04.014', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab monoterapia (CPS ≥1)', 'C14.8', 'Carcinoma escamocelular de cabeza y cuello recurrente/metastásico, PD-L1 CPS ≥1', 1, 'Pembrolizumab 200 mg IV c/21 d hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-048', 'fase_3', 'Burtness B, et al. Lancet 2019;394:1915-1928 (CPS ≥1: SG 12,3 m)', 'https://doi.org/10.1016/S0140-6736(19)32591-7', NULL, 12.3, 19.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab + platino + 5-FU', 'C14.8', 'Carcinoma escamocelular de cabeza y cuello recurrente/metastásico (independiente de CPS)', 1, 'Pembrolizumab 200 mg + cisplatino 100 mg/m² (o carboplatino AUC 5) + 5-FU 1000 mg/m²/d días 1-4, c/21 d ×6 → pembrolizumab', '["pembrolizumab", "cisplatino", "carboplatino", "fluorouracilo"]'::jsonb, 'KEYNOTE-048', 'fase_3', 'Burtness B, et al. Lancet 2019;394:1915-1928', 'https://doi.org/10.1016/S0140-6736(19)32591-7', NULL, 13.0, 36.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Cetuximab + platino + 5-FU (EXTREME)', 'C14.8', 'Carcinoma escamocelular de cabeza y cuello recurrente/metastásico', 1, 'Cetuximab 400→250 mg/m² semanal + cisplatino 100 mg/m² (o carboplatino AUC 5) + 5-FU 1000 mg/m²/d días 1-4, c/21 d ×6 → cetuximab de mantenimiento', '["cetuximab", "cisplatino", "carboplatino", "fluorouracilo"]'::jsonb, 'EXTREME', 'fase_3', 'Vermorken JB, et al. N Engl J Med 2008;359:1116-1127', 'https://doi.org/10.1056/NEJMoa0802656', 5.6, 10.1, 36.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab (2ª línea)', 'C14.8', 'Carcinoma escamocelular de cabeza y cuello R/M, progresión a platino en <6 meses', 2, 'Nivolumab 240 mg IV c/14 d (o 480 mg c/28 d)', '["nivolumab"]'::jsonb, 'CheckMate 141', 'fase_3', 'Ferris RL, et al. N Engl J Med 2016;375:1856-1867', 'https://doi.org/10.1056/NEJMoa1602252', 2.0, 7.5, 13.3, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Gemcitabina + cisplatino (nasofaringe)', 'C11.9', 'Carcinoma nasofaríngeo recurrente o metastásico', 1, 'Gemcitabina 1000 mg/m² días 1 y 8 + cisplatino 80 mg/m² día 1, c/21 d ×6', '["gemcitabina", "cisplatino"]'::jsonb, 'GEM20110714', 'fase_3', 'Zhang L, et al. Lancet 2016;388:1883-1892', 'https://doi.org/10.1016/S0140-6736(16)31388-5', 7.0, 22.1, 64.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dara-VRd (inducción/consolidación en candidato a trasplante)', 'C90.0', 'Mieloma múltiple de nuevo diagnóstico, candidato a TASPE', 1, 'Daratumumab 1800 mg SC + bortezomib 1,3 mg/m² SC d1,4,8,11 + lenalidomida 25 mg VO d1-21 + dexametasona 40 mg, c/28 d: 4 inducción → TASPE → 2 consolidación → mantenimiento dara + lenalidomida', '["daratumumab", "bortezomib", "lenalidomida", "dexametasona"]'::jsonb, 'PERSEUS', 'fase_3', 'Sonneveld P, et al. N Engl J Med 2024;390:301-313 (SLP 4 años 84,3% vs 67,7%)', 'https://doi.org/10.1056/NEJMoa2312054', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('VRd (bortezomib + lenalidomida + dexametasona)', 'C90.0', 'Mieloma múltiple de nuevo diagnóstico', 1, 'Bortezomib 1,3 mg/m² SC d1,4,8,11 + lenalidomida 25 mg VO d1-14 + dexametasona, c/21 d ×8 → mantenimiento lenalidomida', '["bortezomib", "lenalidomida", "dexametasona"]'::jsonb, 'SWOG S0777', 'fase_3', 'Durie BGM, et al. Lancet 2017;389:519-527', 'https://doi.org/10.1016/S0140-6736(16)31594-X', 43.0, 75.0, 82.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Dara-Rd (no candidato a trasplante)', 'C90.0', 'Mieloma múltiple de nuevo diagnóstico, no candidato a TASPE', 1, 'Daratumumab 1800 mg SC (semanal ×8, c/2 sem ×8, luego mensual) + lenalidomida 25 mg VO d1-21 + dexametasona 40 mg semanal, c/28 d hasta progresión', '["daratumumab", "lenalidomida", "dexametasona"]'::jsonb, 'MAIA', 'fase_3', 'Facon T, et al. N Engl J Med 2019;380:2104-2115; actualización: Lancet Oncol 2021;22:1582-1596 (SLP 61,9 m)', 'https://doi.org/10.1056/NEJMoa1817249', 61.9, NULL, 92.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Lenalidomida de mantenimiento post-TASPE', 'C90.0', 'Mieloma múltiple tras trasplante autólogo', 1, 'Lenalidomida 10-15 mg VO/d continuo hasta progresión', '["lenalidomida"]'::jsonb, 'McCarthy (metaanálisis)', 'metanalisis', 'McCarthy PL, et al. J Clin Oncol 2017;35:3279-3289 (SLP 52,8 m vs 23,5 m; HR SG 0,75)', 'https://doi.org/10.1200/JCO.2017.72.6679', 52.8, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('DRd (daratumumab + lenalidomida + dexametasona) en recaída', 'C90.0', 'Mieloma múltiple recaído/refractario, ≥1 línea previa', 2, 'Daratumumab 1800 mg SC + lenalidomida 25 mg VO d1-21 + dexametasona 40 mg semanal, c/28 d', '["daratumumab", "lenalidomida", "dexametasona"]'::jsonb, 'POLLUX', 'fase_3', 'Dimopoulos MA, et al. N Engl J Med 2016;375:1319-1331 (SLP final 44,5 m)', 'https://doi.org/10.1056/NEJMoa1607751', 44.5, NULL, 92.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('DVd (daratumumab + bortezomib + dexametasona) en recaída', 'C90.0', 'Mieloma múltiple recaído/refractario, ≥1 línea previa', 2, 'Daratumumab 1800 mg SC + bortezomib 1,3 mg/m² SC d1,4,8,11 + dexametasona 20 mg, c/21 d ×8 → daratumumab mensual', '["daratumumab", "bortezomib", "dexametasona"]'::jsonb, 'CASTOR', 'fase_3', 'Palumbo A, et al. N Engl J Med 2016;375:754-766 (SLP final 16,7 m)', 'https://doi.org/10.1056/NEJMoa1606038', 16.7, NULL, 83.8, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Kd (carfilzomib + dexametasona)', 'C90.0', 'Mieloma múltiple recaído/refractario, 1-3 líneas previas', 2, 'Carfilzomib 20→56 mg/m² IV días 1-2, 8-9, 15-16 + dexametasona 20 mg, c/28 d', '["carfilzomib", "dexametasona"]'::jsonb, 'ENDEAVOR', 'fase_3', 'Dimopoulos MA, et al. Lancet Oncol 2016;17:27-38', 'https://doi.org/10.1016/S1470-2045(15)00464-7', 18.7, 47.6, 77.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('KRd (carfilzomib + lenalidomida + dexametasona)', 'C90.0', 'Mieloma múltiple recaído, 1-3 líneas previas', 2, 'Carfilzomib 20→27 mg/m² IV d1-2, 8-9, 15-16 + lenalidomida 25 mg d1-21 + dexametasona 40 mg semanal, c/28 d', '["carfilzomib", "lenalidomida", "dexametasona"]'::jsonb, 'ASPIRE', 'fase_3', 'Stewart AK, et al. N Engl J Med 2015;372:142-152', 'https://doi.org/10.1056/NEJMoa1411321', 26.3, 48.3, 87.1, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pomalidomida + dexametasona', 'C90.0', 'Mieloma múltiple refractario a lenalidomida y bortezomib', 3, 'Pomalidomida 4 mg VO d1-21 c/28 d + dexametasona 40 mg semanal', '["pomalidomida", "dexametasona"]'::jsonb, 'MM-003', 'fase_3', 'San Miguel J, et al. Lancet Oncol 2013;14:1055-1066', 'https://doi.org/10.1016/S1470-2045(13)70380-2', 4.0, 12.7, 31.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Teclistamab (biespecífico anti-BCMA)', 'C90.0', 'Mieloma múltiple triple-refractario, ≥3 líneas previas', 4, 'Teclistamab escalamiento 0,06 → 0,3 → 1,5 mg/kg SC, luego 1,5 mg/kg semanal (hospitalización para escalamiento por SLC)', '["teclistamab"]'::jsonb, 'MajesTEC-1', 'fase_2', 'Moreau P, et al. N Engl J Med 2022;387:495-505', 'https://doi.org/10.1056/NEJMoa2203478', 11.3, NULL, 63.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('ABVD (adaptado a PET interino)', 'C81.9', 'Linfoma de Hodgkin clásico, 1ª línea (estadios tempranos y avanzados)', 1, 'Doxorrubicina 25 mg/m² + bleomicina 10 U/m² + vinblastina 6 mg/m² + dacarbazina 375 mg/m² IV días 1 y 15, c/28 d ×2-6; si PET2 negativo puede omitirse bleomicina (AVD)', '["doxorrubicina", "bleomicina", "vinblastina", "dacarbazina"]'::jsonb, 'RATHL', 'fase_3', 'Johnson P, et al. N Engl J Med 2016;374:2419-2429 (SLP 3 años 85,7% con AVD tras PET2 negativo)', 'https://doi.org/10.1056/NEJMoa1510093', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('A-AVD (brentuximab vedotin + AVD)', 'C81.9', 'Linfoma de Hodgkin clásico estadio III-IV, 1ª línea', 1, 'Brentuximab vedotin 1,2 mg/kg + doxorrubicina 25 mg/m² + vinblastina 6 mg/m² + dacarbazina 375 mg/m² IV días 1 y 15, c/28 d ×6, con G-CSF primario', '["brentuximab vedotin", "doxorrubicina", "vinblastina", "dacarbazina", "filgrastim"]'::jsonb, 'ECHELON-1', 'fase_3', 'Ansell SM, et al. N Engl J Med 2022;387:310-320 (SG 6 años 93,9% vs 89,4%)', 'https://doi.org/10.1056/NEJMoa2206125', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Nivolumab + AVD', 'C81.9', 'Linfoma de Hodgkin clásico estadio III-IV (≥12 años), 1ª línea', 1, 'Nivolumab 240 mg + doxorrubicina 25 mg/m² + vinblastina 6 mg/m² + dacarbazina 375 mg/m² IV días 1 y 15, c/28 d ×6', '["nivolumab", "doxorrubicina", "vinblastina", "dacarbazina"]'::jsonb, 'SWOG S1826', 'fase_3', 'Herrera AF, et al. N Engl J Med 2024;391:1379-1389 (SLP 2 años 92% vs 83% con BV-AVD)', 'https://doi.org/10.1056/NEJMoa2405888', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('BEACOPP escalado', 'C81.9', 'Linfoma de Hodgkin clásico avanzado, paciente joven de alto riesgo', 1, 'Bleomicina 10 U/m² d8 + etopósido 200 mg/m² d1-3 + doxorrubicina 35 mg/m² d1 + ciclofosfamida 1250 mg/m² d1 + vincristina 1,4 mg/m² d8 + procarbazina 100 mg/m² d1-7 + prednisona 40 mg/m² d1-14, c/21 d ×4-6 con G-CSF', '["bleomicina", "etopósido", "doxorrubicina", "ciclofosfamida", "vincristina", "procarbazina", "prednisona", "filgrastim"]'::jsonb, 'GHSG HD15', 'fase_3', 'Engert A, et al. Lancet 2012;379:1791-1799', 'https://doi.org/10.1016/S0140-6736(11)61940-5', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('ICE de rescate → TASPE', 'C81.9', 'Linfoma de Hodgkin recaído/refractario, candidato a trasplante autólogo', 2, 'Ifosfamida 5 g/m² (infusión 24 h con mesna) + carboplatino AUC 5 (máx. 800 mg) + etopósido 100 mg/m² d1-3, c/14-21 d ×2-3 → BEAM + TASPE', '["ifosfamida", "carboplatino", "etopósido", "mesna"]'::jsonb, 'MSKCC (Moskowitz)', 'fase_2', 'Moskowitz CH, et al. Blood 2001;97:616-623', 'https://doi.org/10.1182/blood.V97.3.616', NULL, NULL, 88.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Brentuximab vedotin de consolidación post-TASPE', 'C81.9', 'Linfoma de Hodgkin de alto riesgo de recaída tras trasplante autólogo', 2, 'Brentuximab vedotin 1,8 mg/kg IV c/21 d ×16 ciclos iniciando 30-45 días post-TASPE', '["brentuximab vedotin"]'::jsonb, 'AETHERA', 'fase_3', 'Moskowitz CH, et al. Lancet 2015;385:1853-1862 (SLP 42,9 m vs 24,1 m)', 'https://doi.org/10.1016/S0140-6736(15)60165-9', 42.9, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pembrolizumab (recaído/refractario)', 'C81.9', 'Linfoma de Hodgkin recaído/refractario post-TASPE o no candidato a trasplante', 3, 'Pembrolizumab 200 mg IV c/21 d hasta 35 ciclos', '["pembrolizumab"]'::jsonb, 'KEYNOTE-204', 'fase_3', 'Kuruvilla J, et al. Lancet Oncol 2021;22:512-524 (SLP 13,2 m vs 8,3 m con BV)', 'https://doi.org/10.1016/S1470-2045(21)00005-X', 13.2, NULL, 65.6, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Brentuximab vedotin monoterapia', 'C81.9', 'Linfoma de Hodgkin recaído/refractario post-TASPE', 3, 'Brentuximab vedotin 1,8 mg/kg IV c/21 d hasta 16 ciclos', '["brentuximab vedotin"]'::jsonb, 'SG035-0003', 'fase_2', 'Younes A, et al. J Clin Oncol 2012;30:2183-2189 (RC 34%)', 'https://doi.org/10.1200/JCO.2011.38.0410', 5.6, NULL, 75.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('BEP ×3-4', 'C62.9', 'Tumor germinal de testículo (seminoma y no seminoma) diseminado; ×3 buen pronóstico IGCCCG, ×4 intermedio/pobre', 1, 'Bleomicina 30 U IV días 1, 8 y 15 + etopósido 100 mg/m² días 1-5 + cisplatino 20 mg/m² días 1-5, c/21 d sin retrasos; alternativa EP ×4 en buen pronóstico si contraindicación a bleomicina', '["bleomicina", "etopósido", "cisplatino"]'::jsonb, 'Williams (SECSG)', 'fase_3', 'Williams SD, et al. N Engl J Med 1987;316:1435-1440 (BEP superior a PVB; curación >90% en buen pronóstico)', 'https://doi.org/10.1056/NEJM198706043162302', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('VIP (etopósido + ifosfamida + cisplatino)', 'C62.9', 'Tumor germinal de pronóstico intermedio/pobre con contraindicación a bleomicina', 1, 'Etopósido 75 mg/m² + ifosfamida 1,2 g/m² (con mesna) + cisplatino 20 mg/m², todos días 1-5, c/21 d ×4, con G-CSF', '["etopósido", "ifosfamida", "cisplatino", "mesna", "filgrastim"]'::jsonb, 'Nichols (ECOG/SWOG)', 'fase_3', 'Nichols CR, et al. J Clin Oncol 1998;16:1287-1293', 'https://doi.org/10.1200/JCO.1998.16.4.1287', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('TIP de rescate', 'C62.9', 'Tumor germinal recaído tras 1ª línea con platino, rescate convencional', 2, 'Paclitaxel 250 mg/m² infusión 24 h día 1 + ifosfamida 1,5 g/m² días 2-5 (con mesna) + cisplatino 25 mg/m² días 2-5, c/21 d ×4, con G-CSF', '["paclitaxel", "ifosfamida", "cisplatino", "mesna", "filgrastim"]'::jsonb, 'MSKCC TIP (Kondagunta)', 'fase_2', 'Kondagunta GV, et al. J Clin Oncol 2005;23:6549-6555 (RC 70%, SLE durable 63%)', 'https://doi.org/10.1200/JCO.2005.19.638', NULL, NULL, 70.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Carboplatino dosis única adyuvante (seminoma estadio I)', 'C62.9', 'Seminoma estadio I, adyuvancia (alternativa a vigilancia)', NULL, 'Carboplatino AUC 7 IV dosis única', '["carboplatino"]'::jsonb, 'MRC TE19/EORTC 30982', 'fase_3', 'Oliver RT, et al. Lancet 2005;366:293-300 (no inferior a radioterapia)', 'https://doi.org/10.1016/S0140-6736(05)66984-X', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Doxorrubicina monoterapia', 'C49.9', 'Sarcoma de tejidos blandos avanzado o metastásico', 1, 'Doxorrubicina 75 mg/m² IV c/21 d, máximo 6 ciclos (dosis acumulada ≤450 mg/m²)', '["doxorrubicina"]'::jsonb, 'EORTC 62012', 'fase_3', 'Judson I, et al. Lancet Oncol 2014;15:415-423', 'https://doi.org/10.1016/S1470-2045(14)70063-4', 4.6, 12.8, 14.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Doxorrubicina + ifosfamida', 'C49.9', 'Sarcoma de tejidos blandos avanzado, cuando se requiere respuesta objetiva (enfermedad sintomática o potencialmente resecable)', 1, 'Doxorrubicina 75 mg/m² + ifosfamida 10 g/m² (con mesna) c/21 d con G-CSF, hasta 6 ciclos', '["doxorrubicina", "ifosfamida", "mesna", "filgrastim"]'::jsonb, 'EORTC 62012', 'fase_3', 'Judson I, et al. Lancet Oncol 2014;15:415-423 (mayor ORR y SLP sin beneficio en SG)', 'https://doi.org/10.1016/S1470-2045(14)70063-4', 7.4, 14.3, 26.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Epirrubicina + ifosfamida neoadyuvante (alto riesgo)', 'C49.9', 'Sarcoma de tejidos blandos de extremidades/tronco de alto riesgo, neoadyuvancia', NULL, 'Epirrubicina 60 mg/m² días 1-2 + ifosfamida 3 g/m² días 1-3 (con mesna), c/21 d ×3 preoperatorios', '["epirrubicina", "ifosfamida", "mesna"]'::jsonb, 'ISG-STS 1001', 'fase_3', 'Gronchi A, et al. Lancet Oncol 2017;18:812-822', 'https://doi.org/10.1016/S1470-2045(17)30334-0', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Gemcitabina + docetaxel', 'C49.9', 'Sarcoma de tejidos blandos avanzado (opción en leiomiosarcoma); alternativa a doxorrubicina', 1, 'Gemcitabina 675 mg/m² días 1 y 8 + docetaxel 75 mg/m² día 8, c/21 d', '["gemcitabina", "docetaxel"]'::jsonb, 'GeDDiS', 'fase_3', 'Seddon B, et al. Lancet Oncol 2017;18:1397-1410 (no superior a doxorrubicina en 1ª línea)', 'https://doi.org/10.1016/S1470-2045(17)30622-8', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Pazopanib (no adiposo)', 'C49.9', 'Sarcoma de tejidos blandos no adiposo, progresión a quimioterapia', 2, 'Pazopanib 800 mg VO/d continuo', '["pazopanib"]'::jsonb, 'PALETTE', 'fase_3', 'van der Graaf WT, et al. Lancet 2012;379:1879-1886', 'https://doi.org/10.1016/S0140-6736(12)60651-5', 4.6, 12.5, 6.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Trabectedina (liposarcoma/leiomiosarcoma)', 'C49.9', 'Liposarcoma o leiomiosarcoma avanzado, progresión a antraciclina', 2, 'Trabectedina 1,5 mg/m² IV infusión 24 h c/21 d, por catéter central, con dexametasona previa', '["trabectedina"]'::jsonb, 'ET743-SAR-3007', 'fase_3', 'Demetri GD, et al. J Clin Oncol 2016;34:786-793', 'https://doi.org/10.1200/JCO.2015.62.4734', 4.2, NULL, 9.9, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Eribulina (liposarcoma)', 'C49.9', 'Liposarcoma avanzado, progresión a antraciclina', 2, 'Eribulina 1,4 mg/m² IV días 1 y 8, c/21 d', '["eribulina"]'::jsonb, 'Estudio 309', 'fase_3', 'Schöffski P, et al. Lancet 2016;387:1629-1637 (beneficio en SG concentrado en liposarcoma)', 'https://doi.org/10.1016/S0140-6736(15)01283-0', 2.6, 13.5, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Imatinib (GIST avanzado)', 'C49.9', 'Tumor del estroma gastrointestinal (GIST) irresecable o metastásico KIT+', 1, 'Imatinib 400 mg VO/d continuo (800 mg/d si mutación KIT exón 9)', '["imatinib"]'::jsonb, 'B2222 (Demetri)', 'fase_2', 'Demetri GD, et al. N Engl J Med 2002;347:472-480', 'https://doi.org/10.1056/NEJMoa020461', NULL, NULL, 53.7, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Imatinib adyuvante 3 años (GIST alto riesgo)', 'C49.9', 'GIST resecado de alto riesgo de recaída, adyuvancia', NULL, 'Imatinib 400 mg VO/d ×36 meses', '["imatinib"]'::jsonb, 'SSG XVIII/AIO', 'fase_3', 'Joensuu H, et al. JAMA 2012;307:1265-1272 (SG 5 años 92,0% vs 81,7% con 1 año)', 'https://doi.org/10.1001/jama.2012.347', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Sunitinib (GIST 2ª línea)', 'C49.9', 'GIST avanzado con progresión o intolerancia a imatinib', 2, 'Sunitinib 50 mg VO/d 4 semanas sí / 2 no (o 37,5 mg/d continuo)', '["sunitinib"]'::jsonb, 'A6181004 (Demetri)', 'fase_3', 'Demetri GD, et al. Lancet 2006;368:1329-1338 (TTP 27,3 vs 6,4 semanas)', 'https://doi.org/10.1016/S0140-6736(06)69446-4', 6.3, NULL, 7.0, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Regorafenib (GIST 3ª línea)', 'C49.9', 'GIST avanzado, progresión a imatinib y sunitinib', 3, 'Regorafenib 160 mg VO/d, días 1-21 c/28 d', '["regorafenib"]'::jsonb, 'GRID', 'fase_3', 'Demetri GD, et al. Lancet 2013;381:295-302', 'https://doi.org/10.1016/S0140-6736(12)61857-1', 4.8, NULL, 4.5, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Ripretinib (GIST ≥4ª línea)', 'C49.9', 'GIST avanzado, progresión a ≥3 inhibidores de cinasa previos', 4, 'Ripretinib 150 mg VO/d continuo', '["ripretinib"]'::jsonb, 'INVICTUS', 'fase_3', 'Blay JY, et al. Lancet Oncol 2020;21:923-934', 'https://doi.org/10.1016/S1470-2045(20)30168-6', 6.3, 15.1, 9.4, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('MAP (osteosarcoma)', 'C40.9', 'Osteosarcoma de alto grado localizado o metastásico resecable, neoadyuvancia/adyuvancia', NULL, 'Metotrexato 12 g/m² altas dosis con rescate de leucovorina + doxorrubicina 75 mg/m² + cisplatino 120 mg/m², en bloques alternantes ×10 semanas preoperatorias y 19 posoperatorias', '["metotrexato", "leucovorina", "doxorrubicina", "cisplatino"]'::jsonb, 'EURAMOS-1', 'fase_3', 'Marina NM, et al. Lancet Oncol 2016;17:1396-1408 (agregar IE no mejora desenlaces en mala respuesta)', 'https://doi.org/10.1016/S1470-2045(16)30214-5', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('VDC/IE con compresión interválica (sarcoma de Ewing)', 'C40.9', 'Sarcoma de Ewing localizado, tratamiento multimodal', 1, 'Vincristina 2 mg/m² + doxorrubicina 75 mg/m² + ciclofosfamida 1,2 g/m², alternando con ifosfamida 1,8 g/m²/d ×5 + etopósido 100 mg/m²/d ×5, c/14 d con G-CSF ×14 ciclos + control local', '["vincristina", "doxorrubicina", "ciclofosfamida", "ifosfamida", "etopósido", "mesna", "filgrastim"]'::jsonb, 'AEWS0031', 'fase_3', 'Womer RB, et al. J Clin Oncol 2012;30:4148-4154 (SLE 5 años 73% vs 65% c/21 d)', 'https://doi.org/10.1200/JCO.2011.41.5703', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Radioterapia + PCV (glioma de bajo grado de alto riesgo)', 'C71.9', 'Glioma difuso grado 2 de alto riesgo (≥40 años o resección subtotal)', 1, 'Radioterapia 54 Gy → procarbazina 60 mg/m² d8-21 + lomustina 110 mg/m² d1 + vincristina 1,4 mg/m² d8 y 29, c/8 semanas ×6', '["procarbazina", "lomustina", "vincristina"]'::jsonb, 'RTOG 9802', 'fase_3', 'Buckner JC, et al. N Engl J Med 2016;374:1344-1355 (SG 13,3 vs 7,8 años)', 'https://doi.org/10.1056/NEJMoa1500925', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Radioterapia + PCV (oligodendroglioma anaplásico 1p/19q codelecionado)', 'C71.9', 'Oligodendroglioma grado 3 con codeleción 1p/19q', 1, 'Radioterapia 59,4 Gy + PCV (procarbazina + lomustina + vincristina) ×4-6 ciclos (antes o después de RT)', '["procarbazina", "lomustina", "vincristina"]'::jsonb, 'RTOG 9402', 'fase_3', 'Cairncross G, et al. J Clin Oncol 2013;31:337-343 (SG 14,7 vs 7,3 años en codelecionados)', 'https://doi.org/10.1200/JCO.2012.43.2674', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Radioterapia + temozolomida adyuvante (astrocitoma grado 3 sin codeleción)', 'C71.9', 'Astrocitoma anaplásico (grado 3) sin codeleción 1p/19q', 1, 'Radioterapia 59,4 Gy → temozolomida adyuvante 150-200 mg/m²/d días 1-5 c/28 d ×12 ciclos', '["temozolomida"]'::jsonb, 'CATNON (EORTC 26053)', 'fase_3', 'van den Bent MJ, et al. Lancet 2017;390:1645-1653', 'https://doi.org/10.1016/S0140-6736(17)31442-3', NULL, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('Vorasidenib (glioma grado 2 IDH mutado)', 'C71.9', 'Glioma difuso grado 2 IDH1/2 mutado, residual o recurrente tras cirugía, sin necesidad inmediata de QT/RT', 1, 'Vorasidenib 40 mg VO/d continuo', '["vorasidenib"]'::jsonb, 'INDIGO', 'fase_3', 'Mellinghoff IK, et al. N Engl J Med 2023;389:589-601 (SLP 27,7 m vs 11,1 m)', 'https://doi.org/10.1056/NEJMoa2304194', 27.7, NULL, NULL, true, NULL, true);
INSERT INTO protocolos (nombre, cie10, diagnostico, linea_tratamiento, regimen_estandar, moleculas_protocolo, estudio_pivotal, tipo_evidencia, referencia, evidencia_link, pfs_esperado_meses, os_esperado_meses, orr_esperada, requiere_comite, fecha_vigencia, activo) VALUES ('MATRix (linfoma primario de SNC)', 'C83.3', 'Linfoma primario de sistema nervioso central, paciente apto ≤70 años', 1, 'Metotrexato 3,5 g/m² d1 + citarabina 2 g/m² c/12 h d2-3 + tiotepa 30 mg/m² d4 + rituximab 375 mg/m² d-5 y d0, c/21 d ×4 → consolidación con TASPE o WBRT', '["metotrexato", "citarabina", "tiotepa", "rituximab", "leucovorina"]'::jsonb, 'IELSG32', 'fase_2', 'Ferreri AJM, et al. Lancet Haematol 2016;3:e217-e227 (RC 49% con MATRix)', 'https://doi.org/10.1016/S2352-3026(16)00036-3', NULL, NULL, 87.0, true, NULL, true);
