-- ============================================================
-- SGICO: Reemplazo del catálogo de protocolos (203) + migración 020
-- Ejecutar completo en: Supabase SQL Editor (una sola transacción)
-- ============================================================

BEGIN;

-- Migración 020 (idempotente): tipo de estudio y enlace en protocolos
ALTER TABLE protocolos
  ADD COLUMN IF NOT EXISTS tipo_evidencia varchar(30),
  ADD COLUMN IF NOT EXISTS evidencia_link text;

ALTER TABLE protocolos DROP CONSTRAINT IF EXISTS protocolos_tipo_evidencia_check;
ALTER TABLE protocolos ADD CONSTRAINT protocolos_tipo_evidencia_check CHECK (
  tipo_evidencia IS NULL OR tipo_evidencia IN (
    'fase_3', 'fase_2', 'fase_1', 'metanalisis', 'revision_sistematica',
    'guia', 'consenso', 'real_world', 'reporte_caso', 'otro'
  )
);

COMMENT ON COLUMN protocolos.tipo_evidencia IS 'Tipo del estudio que soporta el protocolo (fase_3, fase_2, real_world, ...). Se copia a casos_comite.evidencia_tipo al escoger el protocolo.';
COMMENT ON COLUMN protocolos.evidencia_link IS 'Enlace (DOI / PubMed) del estudio que soporta el protocolo.';


-- Catálogo anterior: desactivar los que usa algún caso o desenlace, borrar el resto
DO $$
DECLARE v_total int;
BEGIN
  SELECT COUNT(*) INTO v_total FROM protocolos;
  RAISE NOTICE 'Protocolos antes de la carga: %', v_total;
END $$;
UPDATE protocolos SET activo = false
 WHERE id IN (SELECT protocolo_id FROM casos_comite WHERE protocolo_id IS NOT NULL
              UNION SELECT protocolo_id FROM desenlaces WHERE protocolo_id IS NOT NULL);
DELETE FROM protocolos p
 WHERE NOT EXISTS (SELECT 1 FROM casos_comite c WHERE c.protocolo_id = p.id)
   AND NOT EXISTS (SELECT 1 FROM desenlaces d WHERE d.protocolo_id = p.id);

DO $$
DECLARE v_act int; v_inact int;
BEGIN
  SELECT COUNT(*) FILTER (WHERE activo), COUNT(*) FILTER (WHERE NOT activo) INTO v_act, v_inact FROM protocolos;
  IF v_act <> 203 THEN
    RAISE EXCEPTION 'ABORT: quedaron % protocolos activos, se esperaban 203', v_act;
  END IF;
  RAISE NOTICE 'Catálogo reemplazado: % protocolos activos; % anteriores desactivados por tener casos', v_act, v_inact;
END $$;
COMMIT;
